  on(container,'pointerleave',event=>{if(event.pointerType==='mouse'){hover=false;schedule();}},{passive:true});
  on(container,'focusin',pause);
  on(container,'focusout',()=>{if(focusFrame)win.cancelAnimationFrame(focusFrame);focusFrame=win.requestAnimationFrame(()=>{focusFrame=0;schedule();});});
  on(container,'keydown',event=>{
   if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;
   event.preventDefault();const slide=event.target.closest('.c11854-slide');
   move(event.key==='Home'?0:event.key==='End'?count-1:(index+(event.key==='ArrowRight'?1:count-1))%count);
   if(slide)slides[index].focus({preventScroll:true});
  });
  on(win,'blur',()=>{windowActive=false;pointer=null;gesture=null;hover=false;pause();});
  on(win,'focus',()=>{windowActive=true;schedule();});
  on(reduced,'change',()=>{if(reduced.matches)track.scrollTo({left:offsets()[index],behavior:'auto'});schedule();});
  const resize=typeof win.ResizeObserver==='function'?new win.ResizeObserver(()=>{if(connected()&&track.clientWidth)track.scrollTo({left:offsets()[index],behavior:'auto'});}):null;
  resize?.observe(track);
