 function schedule(){if(!queued)queued=root.requestAnimationFrame(sync);}
 function reset(){current?.destroy();current=null;gesture=null;blockedUntil=0;remembered={owner:'',id:null,index:0};if(queued)root.cancelAnimationFrame(queued);queued=0;}
