 const owner=()=>JSON.stringify([mobile()?.generation,mobile()?.user?.id,mobile()?.endpoint]);
 function reset(){root.FAWNSEE_COMMERCE_GALLERY11855?.reset();epoch++;scope=owner();wantedQuantity.clear();wantedFavorite.clear();working=null;checkoutWork=null;catalogWork=null;catalogStatus='idle';error='';ctx?.controller?.busy?.delete('commerce11854');}
 function bind(){if(scope!==owner())reset();}
