 function button(action,label,body,attrs='',klass='c11854-icon'){return `<button type="button" class="${klass}"${klass.split(/\s+/).includes('c11854-primary')?' data-font-role="body"':''} data-commerce-action="${action}" aria-label="${esc(label)}" ${attrs}>${body}</button>`;}
 function route(to,label,body,klass='c11854-icon'){return button('route',label,body,`data-route="${esc(to)}"`,klass);}
 function price(cents){return Number.isSafeInteger(cents)&&cents>=0?'¥'+(cents/100).toFixed(2):'价格待确认';}
 function unitPrice(p){return Number.isSafeInteger(p?.price_cents)&&p.price_cents>=0?p.price_cents:null;}
