 function image(p){const mapped=root.FAWNSEE_COMMERCE11854_IMAGES?.[String(p.id)]||root.FAWNSEE_COMMERCE11854_IMAGES?.[p.name]||root.FAWNSEE_COMMERCE11854_IMAGES?.[p.image_key];const named={'杂粮燕麦':'assets/mobile-design/images/today-product-oats11854.webp','轻便收纳盒':'assets/mobile-design/images/today-product-storage11854.webp','运动弹力带':'assets/mobile-design/images/today-product-band11854.webp'}[p.name];const candidate=mapped||named||p.image_path;return candidate&&/^assets\/[a-zA-Z0-9_/.-]+$/.test(candidate)&&!candidate.includes('..')?candidate:helpers.art(p.image_key||'goods');}
 const quantity=id=>wantedQuantity.has(String(id))?wantedQuantity.get(String(id)):Number(state().cart.find(row=>String(row.product_id)===String(id))?.quantity||0);
