 function top(title='生活好物',cart=false){
  const orderDetail=match?.view==='order-detail',orders=['orders','order-detail'].includes(match?.view),back=orderDetail?'#today/goods/orders':cart||['product-detail','orders'].includes(match?.view)?'#today/goods':'#today';
  return `<header class="c11854-header${cart?' c11854-cart-header':''}">${route(back,orderDetail?'返回我的订单':back==='#today/goods'?'返回生活好物':'返回今日',icon('back'))}<h1 data-font-size-fixed>${title}</h1>${cart?`<span class="c11854-count">共 ${totalQuantity()} 件</span>`:`<nav aria-label="好物功能">${button('favorites','我的收藏',icon('star'),`aria-pressed="${match?.view==='goods'&&!!state().ui.goodsFavoritesOnly}"`,'c11854-icon c11854-header-favorite')}${route('#today/goods/cart','购物车',icon('cart')+(totalQuantity()?`<span class="c11854-badge">${totalQuantity()}</span>`:''),'c11854-icon c11854-header-cart')}${button('route','我的订单',icon('orders'),`data-route="#today/goods/orders"${orders?' aria-current="page"':''}`,'c11854-icon c11854-header-orders')}</nav>`}</header>`;
 }
 function totalQuantity(){const ids=new Set([...state().cart.map(row=>String(row.product_id)),...wantedQuantity.keys()]);return [...ids].reduce((sum,id)=>sum+quantity(id),0);}
 function notice(){return error?`<div class="c11854-error" role="alert">${esc(error)}${button('retry','重试','重试','','c11854-text-button')}</div>`:'';}
