 function stepper(p,detail=false){const id=String(p.id),n=detail?detailQuantity(id):quantity(id);if(!detail&&n===0)return button('increase','加入'+p.name,icon('plus')+'<span>加入</span>',`data-id="${safeId(id)}"${!p.is_active?' disabled':''}`,'c11854-add');return `<div class="c11854-stepper" aria-label="${esc(p.name)}数量">${button(detail?'detail-minus':'decrease','减少'+p.name+'数量',icon('minus'),`data-id="${safeId(id)}"${n<=(detail?1:0)?' disabled':''}`)}<input type="number" readonly aria-readonly="true" inputmode="none" min="${detail?1:0}" max="999" step="1" value="${n}" data-commerce-quantity="${safeId(id)}" data-detail="${detail}" aria-label="${esc(p.name)}数量">${button(detail?'detail-plus':'increase','增加'+p.name+'数量',icon('plus'),`data-id="${safeId(id)}"${n>=999||!p.is_active?' disabled':''}`)}</div>`;}
 function productCard(p){const selected=favorite(p.id);return `<article class="c11854-product" data-product="${safeId(p.id)}"><div class="c11854-media">${route('#today/goods/'+p.id,'查看'+p.name,`<img src="${esc(image(p))}" alt="${esc(p.name)}" loading="lazy">`,'c11854-image-button')}${button('favorite',(selected?'取消收藏':'收藏')+p.name,icon('star'),`data-id="${safeId(p.id)}" aria-pressed="${selected}"`,'c11854-icon c11854-favorite'+(selected?' is-selected':''))}</div><div class="c11854-product-info">${route('#today/goods/'+p.id,'查看'+p.name,esc(p.name),'c11854-product-name')}<div class="c11854-product-bottom"><strong class="c11854-price num">${price(unitPrice(p))}</strong>${stepper(p)}</div></div></article>`;}
 function featured(products){
  const slides=products.slice(0,4);if(!slides.length)return '';
  return `<section class="c11854-featured" data-commerce-featured role="region" aria-roledescription="轮播" aria-label="精选商品轮播"><div class="c11854-carousel" aria-live="off">${slides.map((p,i)=>button('route','查看'+p.name,`<img src="${esc(image(p))}" alt="${esc(p.name)}" draggable="false"><span class="c11854-featured-info"><span>${esc(p.name)}</span><strong class="num" data-font-role="title">${price(unitPrice(p))}</strong></span><span class="c11854-featured-badge">本期精选</span>`,`data-route="#today/goods/${safeId(p.id)}" data-commerce-product="${safeId(p.id)}" tabindex="${i===0?'0':'-1'}"`,'c11854-slide')).join('')}</div><div class="c11854-carousel-dots" role="group" aria-label="切换精选商品">${slides.map((p,i)=>`<button type="button" class="c11854-carousel-dot" data-commerce-carousel-index="${i}" aria-label="第${i+1}张：${esc(p.name)}"${i===0?' aria-current="true"':''}></button>`).join('')}</div></section>`;
 }
 function goods(){const s=state(),catalog=s.catalog.filter(p=>p.is_active),query=String(s.ui.goodsQuery||'').trim().toLowerCase(),selected=s.ui.goodsCategory||'all',favoritesOnly=!!s.ui.goodsFavoritesOnly;const categories=[...new Set(catalog.map(p=>categoryOf(p)))];const filtered=catalog.filter(p=>(selected==='all'||(categoryOf(p))===selected)&&(!favoritesOnly||favorite(p.id))&&(!query||[p.name,p.category,categoryOf(p),p.specification].some(value=>String(value||'').toLowerCase().includes(query))));const groups=[...new Set(filtered.map(p=>categoryOf(p)))];return `<div class="today-screen c11854" data-native-screen="goods">${top()}<main><label class="c11854-search">${icon('search')}<input id="t-goods-query11854" type="search" placeholder="搜索商品" value="${esc(s.ui.goodsQuery||'')}" aria-label="搜索商品"></label>${notice()}${!favoritesOnly&&!query&&selected==='all'?featured(catalog):''}<div class="c11854-section-title"><h2>${favoritesOnly?'我的收藏':'商品分类'}</h2>${favoritesOnly?button('all','查看全部商品','全部商品','','c11854-text-button'):''}</div><div class="c11854-categories" aria-label="商品分类">${['all',...categories].map(category=>button('category',category==='all'?'全部':category,esc(category==='all'?'全部':category),`data-category="${esc(category)}" aria-pressed="${selected===category}"`,'c11854-chip'+(selected===category?' is-selected':''))).join('')}</div>${feedback()}${filtered.length?groups.map(category=>`<section class="c11854-category"><div class="c11854-section-title"><h2>${esc(category)}</h2><span>${filtered.filter(p=>(categoryOf(p))===category).length} 件</span></div>${filtered.filter(p=>(categoryOf(p))===category).map(productCard).join('')}</section>`).join(''):`<section class="c11854-empty"><h2>${favoritesOnly?'还没有收藏好物':catalog.length?'没有找到相关商品':catalogStatus==='loading'?'正在加载商品…':catalogStatus==='error'?'商品暂时无法加载':'暂无在售商品'}</h2><p>${favoritesOnly?'点击商品右上角的星形即可收藏。':catalog.length?'试试其他分类或关键词。':catalogStatus==='loading'?'请稍候。':catalogStatus==='error'?'请检查网络后重试。':'稍后再来看看。'}</p></section>`}</main></div>`;}
 function detailQuantity(id){const n=Number(state().ui.productQuantities?.[id]||1);return Number.isInteger(n)?Math.min(999,Math.max(1,n)):1;}
 function notes(p){const usage={'随行饮水杯':'可随行携带，方便日常饮水。','杂粮燕麦':'可作为日常备餐食材，按实际需要选购。','纯棉毛巾':'可用于日常擦拭，使用后请清洁并晾干。','午休靠枕':'可放在座椅或午休区域，按需要调整摆放位置。','轻便收纳盒':'可分类收纳日常小物，方便取用和整理。','运动弹力带':'轻阻力款，实际使用方式请参考商品说明。'},list=[];if(usage[p.name])list.push(usage[p.name]);if(p.specification)list.push('商品规格为'+String(p.specification).slice(0,120)+(p.unit?'，按'+String(p.unit).slice(0,40)+'计价':'')+'。');else if(p.unit)list.push('按'+String(p.unit).slice(0,40)+'计价，请按实际需要选择数量。');else if(p.category)list.push('所属类别为'+String(categoryOf(p)).slice(0,80)+'，请按实际需要选择数量。');return list.slice(0,2);}
 function detail(){const p=state().catalog.find(row=>String(row.id)===String(match.id));if(!p)return `<div class="today-screen c11854">${top()}<main><section class="c11854-empty"><h2>商品暂不可读取</h2>${route('#today/goods','返回生活好物','返回生活好物','c11854-primary')}</section></main></div>`;const n=detailQuantity(String(p.id)),cents=unitPrice(p),remarks=notes(p);return `<div class="today-screen c11854" data-native-screen="product-detail">${top()}<main>${notice()}<img class="c11854-detail-image" src="${esc(image(p))}" alt="${esc(p.name)}"><section class="c11854-detail-info"><h2>${esc(p.name)}</h2><strong class="c11854-price num">${price(cents)}</strong></section>${remarks.length?`<section class="c11854-notes"><h3>备注说明</h3>${remarks.map(note=>`<p>${esc(note)}</p>`).join('')}</section>`:''}<section class="c11854-detail-controls"><div class="c11854-detail-total"><strong class="c11854-price num" data-detail-total>${price(cents===null?null:cents*n)}</strong>${stepper(p,true)}</div>${button('detail-add','加入购物车',icon('plus')+'<span>加入购物车</span>',`data-id="${safeId(p.id)}"${!p.is_active?' disabled':''}`,'c11854-primary')}${!p.is_active?'<p class="c11854-muted">商品已下架</p>':''}${feedback()}</section></main></div>`;}
 function cart(){
  const summary=ctx.controller.store.cartSummary(),lines=summary.items.filter(line=>quantity(line.product_id)>0),total=lines.reduce((sum,line)=>sum+(unitPrice(line.product)??0)*quantity(line.product_id),0),priceKnown=lines.every(line=>unitPrice(line.product)!==null),canCheckout=lines.length>0&&lines.every(line=>line.available)&&priceKnown;
  return `<div class="today-screen c11854" data-native-screen="cart">${top('购物车',true)}<main>${notice()}${feedback()}${lines.length?lines.map(line=>{const p=line.product||{id:line.product_id,name:'商品暂不可用',is_active:false};return `<article class="c11854-cart-item">${route('#today/goods/'+p.id,'查看'+p.name,`<img src="${esc(image(p))}" alt="${esc(p.name)}">`,'c11854-cart-image')}<div class="c11854-cart-info">${route('#today/goods/'+p.id,'查看'+p.name,esc(p.name),'c11854-product-name')}<strong class="num">${price(unitPrice(p))}</strong>${!line.available?'<span class="c11854-muted">已下架</span>':''}<div class="c11854-cart-controls">${stepper({...p,id:line.product_id})}${button('remove','移除'+p.name,'移除',`data-id="${safeId(line.product_id)}"`,'c11854-text-button c11854-remove')}</div></div></article>`;}).join(''):`<section class="c11854-empty">${icon('cart')}<h2>购物车还是空的</h2></section>`}${lines.length?`<section class="c11854-cart-summary"><div><span>合计</span><strong class="c11854-price num">${price(priceKnown?total:null)}</strong></div>${button('checkout','提交订单',icon('orders')+`<span>${checkoutWork?'正在提交…':'提交订单'}</span>`,!canCheckout||working||wantedQuantity.size||checkoutWork?' disabled':'','c11854-primary')}</section>`:''}${route('#today/goods','继续挑选','继续挑选','c11854-secondary')}</main></div>`;
 }
 function orderStatusLabel(order){return ({created:'已提交',pending:'待处理',processing:'处理中',delivered:'已交付',completed:'已完成',cancelled:'已取消',canceled:'已取消',failed:'未完成'})[String(order.status||'')]||'状态待确认';}
 function orderStatus(order){const value=String(order.status||'');return `<span class="c11854-order-status" data-order-status="${esc(value)}">${esc(orderStatusLabel(order))}</span>`;}
 function orderLines(order){return Array.isArray(order.items)?order.items:[];}
