 function orderLine(line){const product=state().catalog.find(p=>String(p.id)===String(line.product_id)),name=String(line.name||line.product_name||'商品'),n=Number(line.quantity),quantityLabel=Number.isSafeInteger(n)&&n>0?n+' 件':'数量待确认';return `<div class="c11854-order-line"><span class="c11854-order-image" aria-hidden="true">${product?`<img src="${esc(image(product))}" alt="" loading="lazy">`:icon('orders')}</span><div><strong>${esc(name)}</strong><small>${esc(quantityLabel)} × ${price(line.unit_price_cents)}</small></div><b class="num">${price(line.subtotal_cents)}</b></div>`;}
