 function redraw(){if(ctx&&/^#today\/goods(?:\/|$)/.test(ctx.getRoute()))ctx.render();}
 function showError(message){error=String(message||'保存未完成，请重试。');redraw();}
 function loadCatalog(){bind();if(catalogWork)return catalogWork;const token={epoch,scope};catalogStatus='loading';const task=(async()=>{try{const rows=array(await mobile().request('shopping.products',{include_inactive:false}));if(!valid(token))return;const catalog=rows.map(p=>({...p,id:String(p.id),remote_id:p.id,is_active:p.is_active!==false,price_kind:'cloud',image_key:p.image_key||(/杯|水|壶/.test(p.name)?'product-bottle':/巾/.test(p.name)?'product-towel':/枕/.test(p.name)?'product-pillow':'goods')}));ctx.controller.store.replaceState({...state(),catalog});catalogStatus='ready';}catch(reason){if(valid(token)){catalogStatus='error';showError(reason.message||'商品暂时无法加载，请重试。');}}finally{if(valid(token)){catalogWork=null;redraw();}}})();catalogWork=task;return task;}
 async function refresh(domain,token){const version=writeVersion[domain],sequence=++readSequence[domain],rows=array(await mobile().request(domain==='cart'?'shopping.cart':'shopping.favorites',{}));if(!valid(token)||version!==writeVersion[domain]||sequence!==readSequence[domain])return false;const patch=domain==='cart'?{cart:rows.map(row=>({...row,product_id:String(row.product_id??row.id),quantity:Number(row.quantity)}))}:{favorites:rows.map(row=>String(typeof row==='object'?(row.product_id??row.id):row))};ctx.controller.store.replaceState({...state(),...patch});return true;}
 function enqueue(){bind();if(working)return working;const token={epoch,scope},task=(async()=>{ctx.controller.busy.add('commerce11854');try{while(valid(token)&&(wantedQuantity.size||wantedFavorite.size)){const quantities=wantedQuantity.size>0,map=quantities?wantedQuantity:wantedFavorite,[id,target]=map.entries().next().value;const actual=quantities?Number(state().cart.find(row=>String(row.product_id)===id)?.quantity||0):state().favorites.some(row=>String(row)===id);if(actual!==target){const domain=quantities?'cart':'favorites';writeVersion[domain]++;if(quantities)await ctx.controller.setCartQuantity(id,target);else await ctx.controller.toggleFavorite(id);if(!valid(token))return;while(valid(token)&&!await refresh(domain,token)){}if(!valid(token))return;const saved=quantities?Number(state().cart.find(row=>String(row.product_id)===id)?.quantity||0):state().favorites.some(row=>String(row)===id);if(saved!==target)throw Error(quantities?'数量尚未保存，请重试。':'收藏尚未保存，请重试。');}if(map.get(id)===target)map.delete(id);redraw();}}catch(reason){if(valid(token)){wantedQuantity.clear();wantedFavorite.clear();showError(reason.message);}}finally{if(valid(token)){ctx.controller.busy.delete('commerce11854');working=null;redraw();}}})();working=task;task.finally(()=>{if(working===task)working=null;});return task;}
