 function action(name,element){bind();const id=element.dataset.id;if(name==='route')return ctx.go(element.dataset.route);if(name==='favorites'){state().ui.goodsFavoritesOnly=true;state().ui.goodsQuery='';state().ui.goodsCategory='all';return ctx.getRoute()==='#today/goods'?redraw():ctx.go('#today/goods');}if(name==='all'){state().ui.goodsFavoritesOnly=false;redraw();}else if(name==='category'){state().ui.goodsCategory=element.dataset.category;redraw();}else if(name==='favorite'){error='';wantedFavorite.set(String(id),!favorite(id));redraw();enqueue();}else if(name==='increase')setQuantity(id,quantity(id)+1);else if(name==='decrease')setQuantity(id,Math.max(0,quantity(id)-1));else if(name==='remove')setQuantity(id,0);else if(name==='detail-minus')setDetailQuantity(id,detailQuantity(id)-1);else if(name==='detail-plus')setDetailQuantity(id,detailQuantity(id)+1);else if(name==='detail-add')setQuantity(id,Math.min(999,quantity(id)+detailQuantity(id)));else if(name==='checkout')checkout();else if(name==='retry'){error='';const token={epoch,scope};Promise.all([loadCatalog(),refresh('cart',token),refresh('favorites',token)]).then(()=>{if(valid(token))redraw();}).catch(reason=>{if(valid(token))showError(reason.message);});}}
