 const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const CSS='html[data-fawnsee-theme][data-primary-page="ai"]:root body .f-app-header .f-app-update-action[data-guest-update]{box-sizing:border-box;display:grid!important;place-items:center;flex:0 0 44px!important;width:44px!important;height:44px!important;min-width:44px!important;min-height:44px!important;padding:10px!important;margin:0!important;border:0!important;border-radius:0!important;background:none!important;box-shadow:none!important;transform:none!important;translate:none!important;color:#365d4c!important;cursor:pointer;transition:color 130ms ease,opacity 130ms ease!important}html[data-fawnsee-theme][data-primary-page="ai"]:root body .f-app-header .f-app-update-action[data-guest-update]>svg{display:block;width:24px!important;height:24px!important;fill:none;stroke:currentColor;stroke-width:1.8}html[data-fawnsee-theme][data-primary-page="ai"]:root body .f-app-header .f-app-update-action[data-guest-update]:active:not(:disabled){color:#1c453b!important;opacity:.65}html[data-fawnsee-theme][data-primary-page="ai"]:root body .f-app-header .f-app-update-action[data-guest-update]:focus-visible{outline:2px solid #4c8979;outline-offset:3px}.guest-cleanup-card{width:min(100%,420px);margin:48px auto;padding:24px;border:1px solid #d6e1d6;border-radius:24px;background:#fffdf8;box-shadow:inset 0 1px #fff,0 4px #d1dfd4;color:#315348}.guest-cleanup-card h1{font-size:23px;line-height:1.5;margin:0 0 12px}.guest-cleanup-card p{font-size:15px;line-height:1.8;overflow-wrap:anywhere}.guest-cleanup-card button{width:100%;min-height:48px;border:1px solid #6aa9a3;border-radius:16px;background:var(--f-action-fill,#317c75);color:#fff;font:inherit;font-weight:650;box-shadow:inset 0 1px #ffffff80,0 4px #245e58}.guest-cleanup-card button:disabled{opacity:.6}.guest-cleanup-status{color:#9d5548}.phone-entry-brand:has([data-phone-back]){flex-wrap:wrap}.phone-entry-brand>[data-phone-back]{width:100%;justify-content:flex-start;margin-bottom:4px}';
 function isGuest(){return !api()?.user;}
