 let ctx=null,installed=false,key='',serial=0,bound=null,inputTimer=0;
 let ui={tab:'discovery',section:'recommended',query:'',posts:[],total:0,next:null,loaded:false,loading:false,error:'',share:null};
 const cache=new Map(),pendingLikes=new Set();
 function identity(){return String(root.FAWNSEE_MOBILE?.user?.id??'')+':'+String(root.FAWNSEE_MOBILE?.generation??0);}
 function bind(){const next=identity();if(next!==key){key=next;serial++;cache.clear();pendingLikes.clear();root.clearTimeout(inputTimer);ui={tab:'discovery',section:'recommended',query:'',posts:[],total:0,next:null,loaded:false,loading:false,error:'',share:null};}return next;}
