 function changeQuery(value){const q=String(value).slice(0,200);if(q===ui.query)return;ui.query=q;ui.section='recommended';ui.share=null;serial++;root.clearTimeout(inputTimer);inputTimer=root.setTimeout(()=>load(),300);const page=doc();page?.querySelector('[data-discovery-action=clear]')?.toggleAttribute('hidden',!q);for(const button of page?.querySelectorAll('[data-discovery-section]')||[])button.setAttribute('aria-selected',String(button.dataset.discoverySection==='recommended'));}
