 async function action(name,value,id){bind();if(name==='tab'){if(!['discovery','forum'].includes(value)||ui.tab===value)return;ui.tab=value;serial++;ui.loading=false;ui.share=null;const page=doc();if(page)page.body.style.removeProperty('overflow');if(value==='forum'){ctx.render();try{await root.FAWNSEE_MOBILE_COMMUNITY_MINE.refreshFeed();if(ui.tab==='forum'&&current())ctx.render();}catch(e){ctx.toast(e.message);}}else{ctx.render();await load();}return;}
  if(name==='section'){if(!['recommended','slow-sugar'].includes(value))return;root.clearTimeout(inputTimer);ui.section=value;ui.query='';const input=doc()?.querySelector('[data-discovery-search]');if(input)input.value='';await load();return;}
  if(name==='clear'){root.clearTimeout(inputTimer);ui.query='';ui.section='recommended';const input=doc()?.querySelector('[data-discovery-search]');if(input){input.value='';input.focus();}await load();return;}
  if(name==='more')return load(true);if(name==='retry')return load(false,true);
  if(name==='new'){cache.clear();ui.loaded=false;return ctx.go('#community/post/new');}if(name==='mine')return ctx.go('#community/mine');
  if(name==='share'){if(post(id))openSheet(id);return;}
  if(name==='share-cancel'){closeSheet();return;}
  if(name==='share-copy'||name==='share-system'){const p=post(ui.share);if(!p)return;const text=String(p.title+'\n'+p.body+'\n—— '+p.author+' · 凡思社区').slice(0,15000),member=identity();try{await root.FAWNSEE_MOBILE.native(name==='share-system'?'native.shareText':'native.copyText',name==='share-system'?{title:String(p.title).slice(0,120),text}:{text});if(member===identity()){closeSheet();ctx.toast(name==='share-system'?'已打开系统分享':'已复制帖子内容');}}catch(error){if(member===identity())ctx.toast(error.message||'分享未完成，请重试。');}return;}
  if(name==='like'){const p=post(id);if(!p||pendingLikes.has(p.id))return;const member=identity();pendingLikes.add(p.id);update();try{await root.FAWNSEE_COMMUNITY.api.like(p.id);if(member===identity())cache.clear();}catch(e){if(member===identity())ctx.toast(e.message);}finally{if(member===identity()){pendingLikes.delete(p.id);update();}}return;}
  if(name==='open'&&post(id)){ctx.go(PATH+encodeURIComponent(id));return;}
 }
 function bindDocument(page){if(!page||bound===page)return;bound=page;
  page.addEventListener('input',event=>{if(event.target.matches('[data-discovery-search]'))changeQuery(event.target.value);});
  page.addEventListener('submit',event=>{if(!event.target.matches('[data-discovery-form]'))return;event.preventDefault();root.clearTimeout(inputTimer);load();});
  page.addEventListener('click',event=>{if(!current())return;const button=event.target.closest('[data-discovery-action]'),cardEl=event.target.closest('[data-discovery-card]');if(button||cardEl){event.preventDefault();event.stopImmediatePropagation();Promise.resolve(action(button?.dataset.discoveryAction||'open',button?.dataset.value,button?.dataset.id||cardEl?.dataset.discoveryCard)).catch(e=>ctx.toast(e.message));}else if(event.target.matches('[data-discovery-mask]'))closeSheet();},true);
  page.addEventListener('keydown',event=>{const dialog=page.querySelector('[data-discovery-share]');if(dialog&&event.key==='Escape'){event.preventDefault();closeSheet();return;}if(dialog&&event.key==='Tab'){const buttons=[...dialog.querySelectorAll('button')];const at=buttons.indexOf(page.activeElement);event.preventDefault();buttons[(at+(event.shiftKey?-1:1)+buttons.length)%buttons.length]?.focus();return;}const cardEl=event.target.closest('[data-discovery-card]');if(cardEl&&event.target===cardEl&&['Enter',' '].includes(event.key)){event.preventDefault();action('open','',cardEl.dataset.discoveryCard);}});
 }
 function sync(){const page=doc();bindDocument(page);if(page&&ui.tab==='discovery'&&!ui.loaded&&!ui.loading&&!ui.error)load();}
 function detail(){return `<div class="member-community today-screen"><style>${css}</style><header class="cd-detail-header"><button class="cd-icon" type="button" data-discovery-back aria-label="返回发现">${svg('back')}</button><h1>帖子详情</h1></header><main class="cd-detail" data-discovery-detail aria-label="帖子详情内容"></main></div>`;}
 function install(value){ctx=value;if(installed)return;installed=true;const views=root.FAWNSEE_COMMUNITY,live=root.FAWNSEE_MOBILE_COMMUNITY_MINE;
  const beforeDecorate=views.decoratePrimary,beforeMatch=views.match,beforeRender=views.render,beforePrepare=live.prepareRoute,beforePublish=views.api.publish;
  views.api.publish=async function(...args){const result=await beforePublish.apply(this,args);cache.clear();return result;};
  views.decoratePrimary=function(...args){return decorate(beforeDecorate.apply(this,args));};
  views.match=function(hash){const match=/^#community\/discovery\/(\d+)$/.exec(hash);return match?{view:'discovery-detail',id:match[1]}:beforeMatch.call(this,hash);};
  views.render=function(route){return route.view==='discovery-detail'?detail():beforeRender.call(this,route);};
  live.prepareRoute=function(hash){bind();return hash==='#community'&&ui.tab==='discovery'?load():beforePrepare.call(this,hash);};
  root.document.addEventListener('load',event=>{if(event.target.id==='main-frame')sync();},true);
  root.addEventListener('message',event=>{if(event.source===root.document.querySelector('#main-frame')?.contentWindow&&event.data?.type==='fawnsee-primary-ready')sync();});
  root.document.addEventListener('click',event=>{if(event.target.closest('[data-discovery-back]')){event.preventDefault();event.stopImmediatePropagation();ui.tab='discovery';ctx.go('#community');}},true);
  const observer=new root.MutationObserver(()=>sync());observer.observe(root.document.body,{childList:true,subtree:true});sync();
 }
 root.FAWNSEE_COMMUNITY_DISCOVERY={install,invalidate:()=>cache.clear(),refresh:()=>load(false,true),snapshot:()=>({tab:ui.tab,section:ui.section,query:ui.query,total:ui.total,count:ui.posts.length,next:ui.next,loading:ui.loading}),_test:{esc,cover}};
