  const markup='<section class="phone-auth-page" data-phone-mode="'+mode+'">'+header+'<main class="phone-auth-content"><div class="phone-auth-heading">'+(erase?'<span class="phone-auth-badge">'+icon('shield')+'账号与资料</span>':'')+'<h1>'+title+'</h1>'+(intro?'<p>'+intro+'</p>':'')+'</div><form class="phone-auth-card" id="phone-auth-form" novalidate>'+body+'<div class="phone-auth-status" data-phone-status role="alert" aria-live="polite" hidden></div>'+(!missing?'<button type="submit" class="phone-auth-submit '+(erase?'is-danger':'')+'" data-phone-submit data-label="'+submitLabel+'">'+submitLabel+'</button>':'')+'</form>'+(mode==='login'?'<button type="button" class="phone-auth-password" data-phone-password>账号/密码登录 <span aria-hidden="true">›</span></button>':'')+'</main></section>';
  const bottom=doc().querySelector('#bottom');if(bottom)bottom.style.display=erase&&!pending?'':'none';
  if(!root.FAWNSEE_EXPERIENCE?.setView?.(markup))doc().querySelector('#view').innerHTML=markup;
