    async function all(action,payload){const out=[];for(let offset=0,iteration=0;iteration<1000;iteration++){
      const result=await request(action,{...payload,limit:100,offset}),items=rows(result);out.push(...items);
      if(!items.length||items.length<100||!Array.isArray(result)&&out.length>=Number(result.total))return out;offset+=items.length;
    }throw Error('资料目录数量异常，请通过关键词查询。');}
    const cacheKey=JSON.stringify([token,key]);
    if(!articleQueries.has(cacheKey)){const work=all('reading.catalog',{query});articleQueries.set(cacheKey,work);work.then(()=>{if(articleQueries.get(cacheKey)===work)articleQueries.delete(cacheKey);},()=>{if(articleQueries.get(cacheKey)===work)articleQueries.delete(cacheKey);});}
