      applyAvatarSnapshot(target,preferences,localAvatar,avatarSnapshot);
      target.display={font_size:preferences.font_size??22,brightness:preferences.brightness??100,theme_color:preferences.theme_color||'sage',city:preferences.city||'北京'};
