      Object.assign(host.style,{width:'44px',height:'44px',minWidth:'44px',flex:'0 0 44px',borderRadius:'50%',overflow:'hidden',display:'grid',placeItems:'center',padding:'0'});
      const data=identity?(value.data||avatarDefaultLogo):'';let image=host.querySelector('[data-ai-user-avatar-image]');
