      if(item){flush();const kind=item[1]?'ol':'ul';if(!list||listKind!==kind){list=doc.createElement(kind);listKind=kind;if(item[1]&&Number(item[1])!==1)list.start=Number(item[1]);node.append(list);}const li=doc.createElement('li');inline(li,item[2]);list.append(li);continue;}
