      knowledge_cards:'M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Zm0 0v15',
      language_cards:'M4 4h16v12H9l-5 4V4m4 5h8m-8 3h5',
