      if(!row||typeof row.id!=='string'||!/^[a-zA-Z0-9_-]{1,128}$/.test(row.id)||seen.has(row.id)||typeof row.kind!=='string'||row.kind.length>80
        ||typeof row.title!=='string'||!row.title.trim()||typeof row.summary!=='string'||row.summary.length>4000)continue;
      const status=['pending','saved','cancelled','expired'].includes(row.status)?row.status:'pending';
      if(status==='pending'&&(typeof row.token!=='string'||!row.token||row.token.length>16384))continue;
