    const key=JSON.stringify([row.web_sources||row.sources||[],row.proposals||[],row.record_drafts||[],row.record_receipts||[],row.record_action_busy,row.record_action_error,row.draft_review_busy,row.draft_review_error,row.draft_review_error_id,row.stream_uncommitted,row.status]);
