      const match=step.detail.match(/^(?:参考了|查询范围：|参考范围：)(.+)[。.]$/);
      if(match){const labels=[...new Set(match[1].split('、').filter(label=>PERSONAL_DOMAINS.has(label.replace(/\s+/g,''))))];if(labels.length)return '查询了'+labels.join('、')+'等个人记录';}
      const records=step.detail.match(/^(?:读取了|参考了|查询了)(\d{1,5})条(?:已保存的)?记录[。.]$/);
