      let writeError=null;
      try{const count=await api('chat.conversations.delete',operation);assertEpoch(token);if(count!==ids.length)throw Error('删除结果尚未核对。');}catch(error){assertEpoch(token);writeError=error;}
      const rows=historyRows(await api('chat.conversations.list'));assertEpoch(token);
      if(ids.some(id=>rows.some(row=>numeric(row.id)===id)))throw writeError||Error('删除结果尚未确认，请保留选择后重试。');
