      const result=await api('chat.messages.list',{conversation_id:number,limit:40});assertEpoch(token);
      const rows=Array.isArray(result)?result:result?.messages||result?.items||[];
      const userIndex=rows.findLastIndex(row=>row.role==='user'&&row.content===operation.content&&(numeric(row.id)||0)>operation.baseline_user_id);
      if(userIndex<0)return;
      const following=rows.slice(userIndex+1),nextUser=following.findIndex(row=>row.role==='user');
      const saved=(nextUser<0?following:following.slice(0,nextUser)).find(row=>row.role==='assistant'&&row.status==='error'
        &&JSON.stringify(root.FAWNSEE_AI_PRESENTATION.normalizedActivity(row.activity))===JSON.stringify(activity));
      if(!saved||!numeric(saved.id))return;
      localMessage.id=String(rows[userIndex].id);
      const existing=conversation.messages.find(row=>String(row.id)===String(saved.id));
      if(existing){const partial=existing.status==='error'&&existing.stream_uncommitted?existing.content:null;Object.assign(existing,mapMessage(saved));if(partial&&!(saved.content||'').trim()){existing.content=partial;existing.stream_uncommitted=true;}}
      else conversation.messages.push(mapMessage(saved));
