      row={id:String(numeric(update.assistant_message_id)||key),client_id:key,role:'assistant',content:'',created_at:new Date().toISOString(),status:'streaming',
        source:'凡思管家',stream_operation:pending.requestId,stream_phase:pending.phase||'thinking',
        activity:root.FAWNSEE_AI_PRESENTATION?.normalizedActivity(pending.activity)||null,web_sources:[],proposals:[],record_drafts:[],tool_steps:[]};
      conversation.messages.push(row);pending.streamMessageId=key;
