    col.className = "flex-1 flex flex-col gap-2";
    const bubble = doc.createElement("div");
    bubble.className = "p-3.5 rounded-2xl bg-surface-container-lowest shadow-sm text-xs leading-relaxed";
    bubble.innerHTML = '<div class="text-xs text-primary font-semibold mb-2">凡思管家</div>' +
      '<p class="text-on-surface-variant whitespace-pre-wrap"></p>';
