    const cancel = () => { const t = active; if (!t) return; active = null;if(t.gesture)root.FAWNSEE_VOICE_GESTURE?.dismiss();resetBar(t);if(t.started!==false)root.FAWNSEE_MOBILE.native('native.cancelVoice').catch(()=>{}); };
