      active = null;if(t.gesture)root.FAWNSEE_VOICE_GESTURE?.dismiss();resetBar(t);
      if (error) { if (error.code !== 'cancelled') setBar(t.bar, '识别未完成', error.message || '请再试一次'); return; }
      const spoken = String(result?.text || '').trim();
