    '[data-ai-chat-role="user"]>[data-ai-chat-column]{flex:0 1 auto!important;width:auto!important;min-width:0!important;max-width:92%!important;align-items:flex-end!important}',
    '[data-ai-chat-role="assistant"]>[data-ai-chat-column]{display:flex!important;flex-direction:column!important;width:100%!important;max-width:none!important;min-width:0!important;gap:4px!important}',
    '[data-ai-assistant-avatar]{display:block!important;box-sizing:border-box!important;flex:0 0 auto!important;width:38px!important;height:38px!important;min-width:38px!important;border:0!important;box-shadow:none!important;background:transparent!important;padding:0!important;margin:0!important;outline:0!important;overflow:hidden;border-radius:50%}',
    '[data-ai-assistant-avatar]>img{display:block!important;width:100%!important;height:100%!important;border:0!important;box-shadow:none!important;background:transparent!important;padding:0!important;margin:0!important;object-fit:cover!important;border-radius:50%!important}',
