    '[data-ai-reply]{width:100%!important;min-height:0!important;height:auto!important}',
    '[data-ai-chat-bubble],.ai-answer-body,[data-ai-reply]>p{font-size:22px!important;line-height:1.5!important;letter-spacing:0!important;transition:none!important}',
    '.ai-answer-body :is(p,h3,h4,ul,ol,li,blockquote,pre),[data-ai-reply]>p{margin-top:0!important;margin-bottom:0!important;line-height:1.5!important;transition:none!important}',
    '.ai-answer-body :is(p,h3,h4,li,blockquote,pre,code){font-size:inherit!important}',
