/* A single active Today gallery. No business writes and no duplicate page timers. */
(function(root){
 'use strict';
 let ctx=null,installed=false,current=null,syncFrame=0,foodWork=null;
 const positions=new WeakMap();
 const INTERVAL=6000;
 function activeDocument(){
  const frame=root.document.querySelector('#main-frame');
  if(!ctx||ctx.getRoute()!=='#today'||!root.FAWNSEE_MOBILE?.user||root.document.hidden||!frame||frame.hidden||frame.style.display==='none')return null;
  try{return frame.contentDocument?.documentElement.dataset.todayLayout==='carousel'?frame.contentDocument:null}catch{return null}
 }
 function create(doc){
  const win=doc.defaultView,container=doc.querySelector('.f-today-carousel'),track=doc.querySelector('.f-carousel-track');
  if(!container||!track)return null;
  const slides=[...track.querySelectorAll('.f-carousel-slide')],dots=[...container.querySelectorAll('.f-carousel-dot')];
  if(slides.length<2||dots.length!==slides.length)return null;
  const count=slides.length;
  const reduced=win.matchMedia('(prefers-reduced-motion: reduce)'),listeners=[];
  let index=Math.max(0,Math.min(count-1,positions.get(doc)||0)),timer=0,frame=0,destroyed=false,hover=false,pointer=null,blockUntil=0;
  const savedTabs=new WeakMap();
  const on=(target,name,fn,options)=>{target.addEventListener(name,fn,options);listeners.push([target,name,fn,options]);};
  const offsets=()=>slides.map(slide=>slide.offsetLeft-slides[0].offsetLeft);
  const canPlay=()=>!destroyed&&activeDocument()===doc&&!doc.hidden&&!reduced.matches&&!hover&&!pointer&&!container.contains(doc.activeElement);
  function pause(){win.clearTimeout(timer);timer=0;}
  function schedule(){pause();if(canPlay())timer=win.setTimeout(()=>{timer=0;if(canPlay())move((index+1)%count,true);},INTERVAL);}
  function mark(){
   positions.set(doc,index);
   slides.forEach((slide,i)=>{
    const active=i===index;
    for(const [name,value] of [['tabindex',active?'0':'-1'],['aria-hidden',String(!active)]])if(slide.getAttribute(name)!==value)slide.setAttribute(name,value);
    if('inert'in slide&&slide.inert===active)slide.inert=!active;
    for(const child of slide.querySelectorAll('button,a,input,select,textarea,[tabindex]')){
     if(!savedTabs.has(child))savedTabs.set(child,child.getAttribute('tabindex'));
     const original=savedTabs.get(child);
     if(active){if(original===null)child.removeAttribute('tabindex');else if(child.getAttribute('tabindex')!==original)child.setAttribute('tabindex',original);}
     else if(child.getAttribute('tabindex')!=='-1')child.setAttribute('tabindex','-1');
    }
    const dot=dots[i];
    if(active&&dot.getAttribute('aria-current')!=='true')dot.setAttribute('aria-current','true');
    else if(!active&&dot.hasAttribute('aria-current'))dot.removeAttribute('aria-current');
   });
   container.dataset.carouselIndex=String(index);
  }
  function read(){frame=0;if(destroyed)return;const at=offsets();if(!track.clientWidth)return;index=at.reduce((best,left,i)=>Math.abs(left-track.scrollLeft)<Math.abs(at[best]-track.scrollLeft)?i:best,0);mark();}
  function requestRead(){if(!frame)frame=win.requestAnimationFrame(read);}
  function move(to,automatic=false){
   if(destroyed||!track.clientWidth)return;
   index=Math.max(0,Math.min(count-1,to));mark();
   track.scrollTo({left:offsets()[index],behavior:reduced.matches?'auto':'smooth'});
   if(!automatic)blockUntil=0;schedule();
  }
  function pointerStart(event){if(event.button!==undefined&&event.button!==0)return;pointer={id:event.pointerId,x:event.clientX,y:event.clientY,moved:false};pause();}
  function pointerMove(event){if(pointer?.id===event.pointerId&&Math.hypot(event.clientX-pointer.x,event.clientY-pointer.y)>9)pointer.moved=true;}
  function pointerEnd(event){if(pointer?.id!==event.pointerId)return;if(pointer.moved)blockUntil=Date.now()+450;pointer=null;schedule();}
  on(track,'scroll',requestRead,{passive:true});
  on(container,'click',event=>{
   const dot=event.target.closest('[data-carousel-index]');
   if(dot?.matches('.f-carousel-dot')){event.preventDefault();move(Number(dot.dataset.carouselIndex));}
  });
  on(doc,'click',event=>{if(Date.now()<blockUntil&&event.target.closest('.f-carousel-slide')){event.preventDefault();event.stopImmediatePropagation();}},true);
  on(track,'pointerdown',pointerStart,{passive:true});on(win,'pointermove',pointerMove,{passive:true,capture:true});
  on(win,'pointerup',pointerEnd,{passive:true,capture:true});on(win,'pointercancel',pointerEnd,{passive:true,capture:true});
  on(container,'pointerenter',event=>{if(event.pointerType==='mouse'){hover=true;pause();}},{passive:true});
  on(container,'pointerleave',event=>{if(event.pointerType==='mouse'){hover=false;schedule();}},{passive:true});
  on(container,'focusin',pause);on(container,'focusout',()=>win.requestAnimationFrame(schedule));
  on(container,'keydown',event=>{
   if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;
   event.preventDefault();const from=event.target.closest('.f-carousel-slide');
   move(event.key==='Home'?0:event.key==='End'?count-1:(index+(event.key==='ArrowRight'?1:count-1))%count);
   if(from)slides[index].focus({preventScroll:true});
  });
  on(doc,'visibilitychange',schedule);on(win,'blur',()=>{pointer=null;hover=false;pause();});on(win,'focus',schedule);
  on(reduced,'change',()=>{if(reduced.matches)track.scrollTo({left:offsets()[index],behavior:'auto'});schedule();});
  const observer=new win.MutationObserver(()=>{
   if(!container.isConnected||doc.querySelector('.f-carousel-track')!==track){syncSoon();return;}
   requestRead();
  });
  observer.observe(container,{childList:true,subtree:true,attributes:true,attributeFilter:['aria-current','aria-hidden','tabindex','inert']});
  const resize=typeof win.ResizeObserver==='function'?new win.ResizeObserver(()=>{if(track.clientWidth)track.scrollTo({left:offsets()[index],behavior:'auto'});}):null;
  resize?.observe(track);
  mark();track.scrollTo({left:offsets()[index],behavior:'auto'});schedule();
  return {doc,container,track,move,schedule,snapshot:()=>({index,timerRunning:!!timer,reduced:reduced.matches,active:activeDocument()===doc,paused:!canPlay()}),destroy(){destroyed=true;pause();if(frame)win.cancelAnimationFrame(frame);observer.disconnect();resize?.disconnect();for(const [target,name,fn,options]of listeners)target.removeEventListener(name,fn,options);}};
 }
 function sync(){
  syncFrame=0;const doc=activeDocument();
  if(current&&(current.doc!==doc||!current.container.isConnected||doc?.querySelector('.f-carousel-track')!==current.track)){current.destroy();current=null;}
  if(!current&&doc)current=create(doc);
  else current?.schedule();
 }
 function syncSoon(){if(!syncFrame)syncFrame=root.requestAnimationFrame(sync);}
 async function openFood(event){
  const frame=root.document.querySelector('#main-frame');
  if(event.source!==frame?.contentWindow||ctx.getRoute()!=='#today'||!root.FAWNSEE_MOBILE?.user)return;
  const routes={'today-food-library':'#today/library/foods','today-recipe-library':'#today/library/recipes'};
  if(event.data?.type!=='fawnsee-primary-action'||!Object.hasOwn(routes,event.data.action))return;
  const generation=root.FAWNSEE_MOBILE.generation;
  if(foodWork?.generation===generation)return;
  const token={generation};foodWork=token;
  try{await ctx.go(routes[event.data.action]);}
  catch(error){if(generation===root.FAWNSEE_MOBILE.generation&&error?.code!=='session_changed')ctx.toast(error.message||'栏目暂时无法打开，请重试。');}
  finally{if(foodWork===token)foodWork=null;}
 }
 function install(value){
  ctx=value;if(installed)return;installed=true;
  root.addEventListener('message',event=>{openFood(event);if(event.source===root.document.querySelector('#main-frame')?.contentWindow&&event.data?.type==='fawnsee-primary-ready')syncSoon();});
  root.document.addEventListener('load',event=>{if(event.target.tagName==='IFRAME')syncSoon();},true);
  root.document.addEventListener('visibilitychange',()=>{if(root.document.hidden){current?.destroy();current=null;}else syncSoon();});
  const observer=new root.MutationObserver(records=>{
   if(records.some(record=>record.target.tagName==='IFRAME'||[...record.addedNodes,...record.removedNodes].some(node=>node.nodeType===1&&(node.tagName==='IFRAME'||node.querySelector('iframe')))))syncSoon();
  });
  observer.observe(root.document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['id','hidden','style']});
  root.addEventListener('pagehide',()=>{current?.destroy();current=null;if(syncFrame)root.cancelAnimationFrame(syncFrame);syncFrame=0;});
  root.addEventListener('pageshow',syncSoon);syncSoon();
 }
 root.FAWNSEE_TODAY_CAROUSEL={install,snapshot:()=>current?.snapshot()||{active:false,timerRunning:false},interval:INTERVAL};
})(globalThis);

