 const ICONS={back:'<path d="m14 5-7 7 7 7"/>',arrow:'<path d="m9 5 7 7-7 7"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9Z"/>',leaf:'<path d="M20 3C8 2 3 9 6 16c6 6 15-2 14-13ZM6 20 17 7"/>',fork:'<path d="M5 3v7a3 3 0 0 0 6 0V3M8 3v19M19 3c-5 4-5 10 0 10V3Zm0 10v9"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6m1 4a5 5 0 0 1 4 5"/>',reload:'<path d="M20 11a8 8 0 1 0-2 6M20 4v7h-7"/>'};
 const NUTRIENTS=[['energy_kcal','能量','千卡'],['carbohydrate_g','碳水化合物','克'],['protein_g','蛋白质','克'],['fat_g','脂肪','克'],['fiber_g','膳食纤维','克'],['calcium_mg','钙','毫克'],['iron_mg','铁','毫克'],['sodium_mg','钠','毫克'],['potassium_mg','钾','毫克'],['vitamin_c_mg','维生素 C','毫克']];
