 function categories(kind){return [...new Set(['全部',...(catalog()[kind==='foods'?'categories':'recipe_categories']||[]).map(value=>typeof value==='string'?value:value.name||value.label).filter(Boolean),...items(kind).map(item=>item.category).filter(Boolean),'收藏'])];}
 function filtered(kind){const search=query[kind].trim().toLocaleLowerCase('zh-CN'),selected=category[kind];return items(kind).filter(item=>(selected==='全部'||selected==='收藏'&&favorites[kind].includes(item.id)||selected===item.category)&&(!search||[item.name,item.category,item.summary,...(item.aliases||[]),...(item.ingredients||[]).map(value=>value.name)].filter(Boolean).join(' ').toLocaleLowerCase('zh-CN').includes(search)));}
 const image=item=>'<img class="try-library-image" src="'+esc(IMAGES[item.id]||'')+'" alt="'+esc(item.name)+'配图" loading="lazy" decoding="async" width="240" height="240">';
