 function favoritesEntry(kind){return '<button type="button" class="try-library-favorites" data-try-library-favorites="'+kind+'" aria-label="查看收藏'+title(kind)+'" aria-pressed="'+(category[kind]==='收藏')+'">'+icon('star')+'</button>';}
