  root.document.addEventListener('keydown',event=>{const button=event.target.closest?.('[data-try-library-category]');if(!button||!active()||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const parsed=parse(route());if(!parsed||parsed.id)return;const kind=parsed.kind,names=categories(kind),index=names.indexOf(category[kind]),next=event.key==='Home'?0:event.key==='End'?names.length-1:(index+(event.key==='ArrowRight'?1:-1)+names.length)%names.length;category[kind]=names[next];refresh();[...root.document.querySelectorAll('[data-try-library-category]')].find(node=>node.dataset.tryLibraryCategory===names[next])?.focus();});
  root.addEventListener?.('hashchange',()=>{if(owner!==identity())bind();});
