function seed(){const d=today(),p=new Date(d+'T12:00:00+08:00');p.setUTCDate(p.getUTCDate()-1);const yesterday=p.toISOString().slice(0,10);return [{id:uid(),cat:'water',date:d,time:'08:10',volume:250,notes:'',history:[]},{id:uid(),cat:'diet',date:d,time:'08:25',meal:'早餐',food:'燕麦粥、鸡蛋',calories:340,notes:'',history:[]},{id:uid(),cat:'metric',metric:'weight',date:d,time:'08:00',value:62.4,unit:'kg',notes:'',history:[]},{id:uid(),cat:'water',date:d,time:'10:40',volume:200,notes:'温水',history:[]},{id:uid(),cat:'metric',metric:'glucose',date:d,time:'09:00',value:5.7,unit:'mmol/L',context:'空腹',notes:'',history:[]},{id:uid(),cat:'sleep',date:yesterday,time:'07:20',hours:7.5,notes:'',history:[]},{id:uid(),cat:'metric',metric:'weight',date:yesterday,time:'08:05',value:62.6,unit:'kg',notes:'',history:[]}].map(x=>({...x,created:new Date().toISOString(),source:'记录'}))}
function persist(){}let toastTimer;function toast(s){$('#toast').textContent=s;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',2800)}
let todayRestore=true,todayPending=0;let route='#ai',selectedDate=today(),filter='all',lastMetric='weight',formBaseline='',saving=false,voicePhase='idle',voiceError='',voiceText='',voiceTimer=null,trendMetric='water',trendRange='7',trendStart='',trendEnd='',trendContext='全部',trendName='全部',trendUnit='mmol/L';
const navs=[['today','今日'],['records','生活记录'],['ai','智能助手'],['community','社区交流'],['mine','我的']];
function nav(){const active=route.slice(1).split('/')[0];$('#bottom').innerHTML=navs.map(([id,label])=>`<button type="button" data-go="#${id}" class="${active===id||!['today','ai','community','mine'].includes(active)&&id==='records'?'active':''}" ${active===id?'aria-current="page"':''}><span class="nav-icon">${icon(id)}</span><span>${label}</span></button>`).join('');$('#bottom').style.display='grid'}
function header(){return `<header><div class="brand"><img src="${ASSETS.logo}" alt="凡思标志"><div><strong>凡思生活</strong></div></div><span class="badge"></span></header>`}
function back(title,target='#records'){return `<div class="backline"><button type="button" class="iconbtn" data-go="${target}" aria-label="返回">${icon('back')}</button><h1>${E(title)}</h1></div>`}
function hero(art,kicker,title,sub,compact=false){return `<section class="hero ${compact?'compact':''}"><img src="${ASSETS[art]}" alt="凡思原创${art==='meal'?'餐饮与饮水':art==='rest'?'休息与居住环境':art==='voice'?'语音心流':'健康手账'}插画"><div class="hero-content"><h2>${title}</h2><p>${sub}</p></div></section>`}
function styleCat(cat){return `--color:${CATS[cat].color};--tint:${CATS[cat].tint}`}
function recordDisplayText(value){return ({'合成演示第二次通风':'第二次通风','演示第二次生活健康回顾':'第二次生活健康回顾'})[value]??value}function recordUnitLabel(unit){const labels={kg:'千克',cm:'厘米',ml:'毫升',mL:'毫升',mmHg:'毫米汞柱','mmol/L':'毫摩尔/升','mg/dL':'毫克/分升',g:'克',mg:'毫克',kcal:'千卡'};return Object.prototype.hasOwnProperty.call(labels,unit)?labels[unit]:unit}function sum(r){if(r.cat==='diet')return `${r.meal||'饮食'} · ${r.food}`;if(r.cat==='water')return `饮水 ${r.volume} 毫升`;if(r.cat==='activity')return [r.activity,r.duration!==''&&r.duration!=null?`${r.duration} 分钟`:'',r.steps!==''&&r.steps!=null?`${r.steps} 步`:''].filter(Boolean).join(' · ');if(r.cat==='sleep')return `睡眠 ${r.hours} 小时`;if(r.cat==='environment')return [r.temperature!==''&&r.temperature!=null?`${r.temperature} ℃`:'',r.humidity!==''&&r.humidity!=null?`湿度 ${r.humidity}%`:'',r.ventilation!==''&&r.ventilation!=null?`通风 ${r.ventilation} 分钟`:'',r.quality!==''&&r.quality!=null?`居住感受 ${r.quality} 分`:'',recordDisplayText(r.description)].filter(Boolean).join(' · ');if(r.cat==='medical')return recordDisplayText(r.name);return `${({weight:'体重',glucose:'血糖',blood_pressure:'血压',lipids:'血脂',height:'身高',custom:'自定义'})[r.metric]||'指标'} ${r.metric==='blood_pressure'?`${r.value}/${r.diastolic??''} ${recordUnitLabel(r.unit)}`:`${r.value} ${recordUnitLabel(r.unit)}`}`}
function secondary(r){if(r.cat==='diet'&&r.calories!==''&&r.calories!=null)return `${r.calories} 千卡${r.estimated?' · AI估算':''}`;if(r.cat==='metric'&&r.metric==='glucose')return r.context||'未说明';const note=r.notes||r.location||'';return String(note).trim()==='合成演示记录'?'':note}
function recordItem(r){return `<button class="record" type="button" data-record-kind="${r.cat}" data-go="#detail/${r.id}" style="${styleCat(r.cat)}"><span class="record-icon">${icon(r.cat)}</span><span class="record-content"><span class="row"><strong class="small">${CATS[r.cat].label}</strong><time class="num">${E(r.time)}</time></span><p>${E(sum(r))}</p>${secondary(r)?`<span class="small muted">${E(secondary(r))}</span>`:''}</span>${icon('chevron','chevron')}</button>`}
function sorted(list){return [...list].sort((a,b)=>(b.date+'T'+b.time).localeCompare(a.date+'T'+a.time)||String(b.created).localeCompare(String(a.created)))}
function recordsPage(){let list=sorted(state.records.filter(r=>r.date===selectedDate&&(filter==='all'||r.cat===filter)));return `${header()}<main class="page">${hero('journal','YOUR DAILY JOURNAL','一日一页<br>生活有迹可循','').replace('class="hero ', 'class="hero f-records-banner ').replace('<p></p>', '')}<button class="voice-entry" data-record-voice-hold type="button" style="touch-action:none;user-select:none"><span class="orb">${icon('mic')}</span><span><strong>长按进行语音智能记录</strong><small data-record-voice-hint data-font-size-fixed="true">说一段日常，整理成生活记录</small></span></button>${FAWNSEE_RECORD_VOICE.render()}<section class="categories" aria-label="七类生活记录">${Object.entries(CATS).map(([cat,c])=>`<button class="category" data-font-role="body" data-font-size-fixed="true" data-go="#form/${cat}" style="${styleCat(cat)}"><span class="cat-icon">${icon(cat)}</span><span>${c.label}</span></button>`).join('')}</section><div class="section-head"><h2>今天的生活片段</h2><button class="linkbtn" data-go="#trends">${icon('trend')}趋势分析</button></div><div class="datebar"><button class="iconbtn" data-action="prev-date" aria-label="前一天">${icon('back')}</button><input id="list-date" type="date" value="${selectedDate}" aria-label="记录日期"><button class="iconbtn" data-action="next-date" aria-label="后一天">${icon('chevron')}</button></div><div class="pillrow" aria-label="筛选类别"><button class="chip ${filter==='all'?'active':''}" data-filter="all">全部</button>${Object.entries(CATS).map(([k,c])=>`<button class="chip ${filter===k?'active':''}" data-filter="${k}">${c.label}</button>`).join('')}</div><p class="small muted">${list.length} 条记录 · 按发生时间排列</p>${list.length?`<div class="timeline">${list.map(recordItem).join('')}</div>`:`<section class="empty"><img src="${ASSETS.journal}" alt="植物与手账插画"><h3>${filter==='all'?'这里还没有生活记录':'这一天还没有'+CATS[filter].label+'记录'}</h3><p class="small muted">从一杯水、一顿饭开始，给今天留下第一笔。</p><button class="primary" data-go="#form/${filter==='all'?'water':filter}">${icon(filter==='all'?'water':filter)}记录${filter==='all'?'饮水':CATS[filter].label}</button></section>`}<p class="notice"></p></main>`}
function input(name,label,type='text',value='',attrs='',hint=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${E(value)}" ${attrs}>${hint?`<small>${hint}</small>`:''}</div>`}
function area(name,label,value='',voice=false,photos=[]){return `<div class="field"${voice?' data-record-photo-field="'+name+'"':''}><label for="f-${name}">${label}</label>${voice?'<div class="record-photo-input">':''}<textarea id="f-${name}" name="${name}">${E(value)}</textarea>${voice?'<input type="hidden" name="record_photo_ids" value="'+E(typeof photos==='string'?photos:JSON.stringify(photos))+'"><div class="record-photo-previews" data-record-photo-previews aria-live="polite"></div></div><button type="button" class="record-photo-button" data-record-photo-pick="'+name+'"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h4l2-3h4l2 3h4v13H4Z"></path><circle cx="12" cy="13" r="4"></circle></svg><span>拍照输入</span></button><button type="button" class="voice-bar" data-voice-hold="'+name+'" aria-label="语音输入"><svg class="vb-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0Z"></path><path d="M5 11v1a7 7 0 0 0 14 0v-1"></path><path d="M12 19v3"></path></svg><span class="vb-label">语音输入</span><span class="vb-hint">按住 说话</span></button>':''}</div>`}
function select(name,label,options,value){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(o=>{const[v,l]=Array.isArray(o)?o:[o,o];return `<option value="${v}" ${v==value?'selected':''}>${l}</option>`}).join('')}</select></div>`}
function fields(cat,r){
 const req='<span class="required">*</span>',photos=r.photo_file_ids||r.record_photo_ids||[];
 const description=(name,label,value,placeholder,voice=false)=>area(name,label,value||'',voice,photos).replace('<textarea ','<textarea placeholder="'+E(placeholder)+'" ');
 const notes=placeholder=>description('notes','其他说明',r.notes,placeholder);
 if(cat==='diet')return select('meal','餐次',[...(r.meal==='未说明'?['未说明']:[]),'早餐','午餐','晚餐','加餐'],r.meal||'午餐')+description('food','吃了什么 '+req,r.food,'',true)+input('calories','热量 · 千卡','number',r.calories??'','min="0" max="20000" step="1" inputmode="numeric" placeholder="可选填"')+notes('可选填，用于了解吃饭时的其他情况');
 if(cat==='water')return input('volume','饮水量 · 毫升 '+req,'number',r.volume??250,'required min="1" max="10000" step="any" inputmode="decimal"')+`<div class="pillrow">${[100,200,250,500].map(n=>`<button type="button" class="chip" data-volume="${n}">${n} 毫升</button>`).join('')}</div>`+notes('可选填，用于了解饮水时的其他情况');
 if(cat==='activity')return input('activity','运动方式 '+req,'text',r.activity||'','required maxlength="120" placeholder="例如：散步"')+`<div class="grid2">${input('duration','时长/分钟','number',r.duration??'','min="0" max="1440" step="1" inputmode="numeric"')}${input('steps','步数','number',r.steps??'','min="0" max="200000" step="1" inputmode="numeric"')}</div>`+notes('可选填，用于了解运动时的其他情况');
 if(cat==='sleep')return input('hours','睡眠时长 · 小时 '+req,'number',r.hours??'','required min="0" max="24" step="any" inputmode="decimal"')+notes('可选填，用于了解睡眠时的其他情况');
 if(cat==='environment')return `<div class="grid2">${input('temperature','室温 · ℃','number',r.temperature??'','min="-80" max="80" step="any" inputmode="decimal"')}${input('humidity','湿度 · %','number',r.humidity??'','min="0" max="100" step="any" inputmode="decimal"')}</div>`+description('description','环境情况',r.description,'可选填，用于详细了解居住环境',true);
 if(cat==='medical')return '<input type="hidden" name="event_type" value="'+E(['consultation','medication','other'].includes(r.event_type)?r.event_type:'other')+'">'+input('name','事项名称 '+req,'text',r.name||'','required maxlength="160" placeholder="例如：门诊复查"')+input('location','地点或机构','text',r.location||'','maxlength="160"')+description('description','具体事项',r.description,'建议填写，用于了解医疗情况',true);
 if(cat==='metric'){
  const m=r.metric||lastMetric,kinds=[['weight','体重'],['glucose','血糖'],['blood_pressure','血压'],['lipids','血脂'],['height','身高'],['custom','自定义']];
  const unit=r.id||Object.hasOwn(r,'unit')?r.unit||'':({weight:'kg',height:'cm',blood_pressure:'mmHg',glucose:'mmol/L',lipids:'mmol/L',custom:''}[m]||'');
  const label=({weight:'体重',glucose:'血糖',blood_pressure:'收缩压',lipids:'血脂',height:'身高',custom:''}[m]||'');
  return '<div class="pillrow" role="group" aria-label="身体指标类型" style="flex-wrap:wrap;overflow:visible">'+kinds.map(([value,text])=>'<button type="button" class="chip '+(m===value?'active':'')+'" data-metric="'+value+'">'+text+'</button>').join('')+'</div><input type="hidden" name="metric" value="'+E(m)+'"><input type="hidden" name="unit" value="'+E(unit)+'">'+(m==='custom'?input('metric_name','指标名称 '+req,'text',r.metric_name||'','required maxlength="100" placeholder="例如：体脂率"'):'')+(m==='lipids'?input('metric_name','指标项目','text',r.metric_name||'','maxlength="100" placeholder="例如：总胆固醇"'):'')+input('value',label+'数值 '+req,'number',r.value??'','required min="0.000001" step="any" inputmode="decimal" placeholder="'+E(unit||'无单位')+'"')+(m==='blood_pressure'?input('diastolic','舒张压数值 '+req,'number',r.diastolic??'','required min="0.000001" step="any" inputmode="decimal" placeholder="'+E(unit)+'"'):'')+(m==='glucose'?select('context','测量情境',['未说明','空腹','餐前','餐后','随机'],r.context||'未说明'):'')+notes('可选填，用于了解该项目身体的其他情况');
 }
 return '';
}

function currentFormData(){const f=$('#record-form');if(!f)return{};return Object.fromEntries(new FormData(f))}
function formPage(cat,id){const old=id?state.records.find(r=>r.id===id):null;if(id&&!old)return notFound();const draft=state.drafts[cat];let r=old?{...old}:draft?{...draft}:{date:today(),time:clock(),metric:lastMetric};if(cat==='metric')lastMetric=r.metric||lastMetric;let c=CATS[cat];return `${header()}<main class="page">${back(old?'编辑'+c.label:'记录'+c.label,old?'#detail/'+id:'#records')}${hero(c.art,'A MOMENT TO REMEMBER',cat==='diet'?'好好吃饭<br>也是爱自己':cat==='water'?'一杯水的<br>温柔时刻':cat==='activity'?'每一步<br>都有自己的节奏':cat==='sleep'?'把休息<br>还给自己':cat==='environment'?'舒适的空间<br>从觉察开始':cat==='medical'?'发生过的事<br>清楚地留存':'看见身体的<br>细微变化','留一份真实的日常。',true).replace('<p>', '<p data-record-form-subtitle data-font-size-fixed="true">')}${draft&&!old?'<div class="success">已恢复暂存草稿，可继续填写。</div>':''}<form id="record-form" data-cat="${cat}" data-id="${id||''}"><div class="grid2">${input('date','记录日期 <span class="required">*</span>','date',r.date,'required')}${input('time','发生时间 <span class="required">*</span>','time',r.time,'required')}</div>${fields(cat,r)}${old?area('reason','修改原因 <span class="required">*</span>',''):''}<div id="form-error" class="err" role="alert"></div><div class="actions ${old?'':'two'}"><button class="primary" type="button" data-save-mode="done" name="saveMode" value="done">${icon('check')}${old?'保存修改':'保存记录'}</button>${old?'':`<button class="secondary" type="button" data-save-mode="draft" name="saveMode" value="draft">${icon('check')}暂时保存</button>`}</div><button class="f-try1-cancel" type="button" data-go="${old?'#detail/'+id:'#records'}">取消${old?'修改':'填写'}</button></form></main>`}
function validate(cat,v,edit){if(!/^\d{4}-\d{2}-\d{2}$/.test(v.date||'')||!Number.isFinite(new Date(v.date+'T00:00:00+08:00').getTime()))return'请选择有效的记录日期。';if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(v.time||''))return'请选择有效的发生时间。';const ranges={calories:[0,20000,true],volume:[1,10000,false],duration:[0,1440,true],steps:[0,200000,true],hours:[0,24,false],temperature:[-80,80,false],humidity:[0,100,false],ventilation:[0,1440,true],quality:[0,100,false]};for(let[k,[min,max,int]]of Object.entries(ranges)){if(v[k]!==undefined&&v[k]!==''){let n=Number(v[k]);if(!Number.isFinite(n)||n<min||n>max||(int&&!Number.isInteger(n)))return `${({calories:'热量',volume:'饮水量',duration:'运动时长',steps:'步数',hours:'睡眠时长',temperature:'室温',humidity:'湿度',ventilation:'通风时间',quality:'居住感受'})[k]}需为 ${min}–${max} ${int?'的整数':'之间的数值'}。`}}
const required={diet:['food'],water:['volume'],activity:['activity'],sleep:['hours'],medical:['name'],metric:['value']};for(let k of required[cat]||[])if(String(v[k]??'').trim()==='')return'请填写所有标有 * 的必填内容。';if(cat==='metric'&&(!Number.isFinite(Number(v.value))||Number(v.value)<=0))return'指标数值必须大于 0。';if(cat==='environment'&&!['temperature','humidity','ventilation','quality','description','notes'].some(k=>String(v[k]??'').trim()!==''))return'请至少填写一项环境情况。';if(edit&&!v.reason.trim())return'请填写简短的修改原因。';return''}
function error(s){const el=$('#form-error');el.textContent=s;el.classList.add('show');el.scrollIntoView({behavior:'smooth',block:'center'})}
function requestSave(mode='done'){const f=$('#record-form');if(!f)return;saveForm({preventDefault(){},target:f,submitter:{value:mode}})}
async function saveForm(ev){return FAWNSEE_MOBILE.saveRecord(ev);}
function detailPage(id){const r=state.records.find(r=>r.id===id);if(!r)return notFound();let fieldsMap={diet:[['餐次',r.meal],['食物',r.food],['热量',r.calories!==''&&r.calories!=null?`${r.calories} 千卡${r.estimated?' · AI估算':''}`:'未填写'],['含糖量',r.sugar_g!==''&&r.sugar_g!=null?`${r.sugar_g} 克`:'未填写']],water:[['饮水量',`${r.volume} 毫升`]],activity:[['运动方式',r.activity],['时长',r.duration!==''&&r.duration!=null?`${r.duration} 分钟`:'未填写'],['步数',r.steps!==''&&r.steps!=null?`${r.steps} 步`:'未填写']],sleep:[['睡眠时长',`${r.hours} 小时`]],environment:[['室温',r.temperature!==''&&r.temperature!=null?`${r.temperature} ℃`:'未填写'],['湿度',r.humidity!==''&&r.humidity!=null?`${r.humidity}%`:'未填写'],['通风',r.ventilation!==''&&r.ventilation!=null?`${r.ventilation} 分钟`:'未填写'],['居住感受',r.quality!==''&&r.quality!=null?`${r.quality} 分`:'未填写'],['环境情况',r.description||'未填写']],medical:[['事项名称',r.name],['地点或机构',r.location||'未填写'],['事实说明',r.description||'未填写']],metric:[['指标',({weight:'体重',glucose:'血糖',blood_pressure:'血压',lipids:'血脂',height:'身高',custom:'自定义'})[r.metric]||'指标'],...(r.metric_name?[['指标名称',r.metric_name]]:[]),['数值',`${r.value} ${r.unit}`],...(r.metric==='blood_pressure'?[['舒张压',`${r.diastolic??''} ${r.unit}`]]:[]),...(r.metric==='glucose'?[['测量情境',r.context||'未说明']]:[])]};return `${header()}<main class="page">${back('记录详情')}${hero(CATS[r.cat].art,'YOUR LIFE, YOUR STORY',CATS[r.cat].label+'里的<br>一个小片段',r.date+' · '+r.time,true)}<section class="card"><div class="row" style="${styleCat(r.cat)}"><span class="record-icon">${icon(r.cat)}</span><div><h2>${CATS[r.cat].label}</h2><span class="small muted">${r.source||'记录'}</span></div><span class="badge" style="margin-left:auto">v${1+(r.history||[]).length}</span></div><dl><div class="kv"><dt>发生时间</dt><dd class="num">${r.date} ${r.time}</dd></div>${fieldsMap[r.cat].map(([k,v])=>`<div class="kv"><dt>${k}</dt><dd>${E(v)}</dd></div>`).join('')}${r.cat!=='medical'?`<div class="kv"><dt>备注</dt><dd>${E(r.notes||'未填写')}</dd></div>`:''}</dl></section><div class="actions two"><button class="primary" data-go="#edit/${id}">${icon('edit')}编辑记录</button><button class="secondary danger" data-delete="${id}">${icon('trash')}删除记录</button></div><div class="section-head"><h2>修改历史</h2>${icon('history')}</div><section class="card">${(r.history||[]).length?[...r.history].reverse().map((h,i)=>`<div class="version"><strong>v${r.history.length+1-i} · ${E(h.reason)}</strong><small>${new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',dateStyle:'short',timeStyle:'short'}).format(new Date(h.at))}</small><p class="muted">修改前：${E(h.before)}</p><p>修改后：${E(h.after)}</p></div>`).join(''):'<p class="small muted">首次记录，尚无修改。</p>'}<div class="version"><strong>v1 · 创建记录</strong><small>${E(r.date)} ${E(r.time)}</small></div></section></main>`}
function notFound(){return `${header()}<main class="page">${back('记录不存在')}<div class="empty"><h2>这条记录已移除</h2><button class="primary" data-go="#records">返回生活记录</button></div></main>`}
function voicePage(){const base=`${header()}<main class="page">${back('语音智能记录')}<h1>把今天，慢慢说</h1><p class="muted small">一次说几件事，也能各自留下一条记录。</p><div class="voice-art"><img src="${ASSETS.voice}" alt="ChatGPT 原创凡思语音心流插画"><span class="caption">说出来，让日常有迹可循</span></div>`;if(['starting','transcribing'].includes(voicePhase))return base+`<section class="card voice-center" aria-live="polite"><h2>${voicePhase==='starting'?'正在准备麦克风':'识别中…'}</h2><p class="small muted">识别出的文字会逐步显示，完成后可核对修改。</p><textarea id="transcript" rows="4" disabled>${E(voiceText)}</textarea><button class="secondary" data-action="cancel-voice">取消本次语音</button></section></main>`;if(voicePhase==='processing')return base+`<section class="card voice-center" aria-live="polite"><div class="wave">${'<i></i>'.repeat(17)}</div><h2>正在整理生活片段</h2><p class="small muted">拆分类别 · 核对时间与单位</p><div class="skeleton"></div><div class="skeleton" style="width:55%"></div><button class="secondary" data-action="cancel-voice">取消整理</button></section></main>`;return base+`<section class="card voice-center"><p class="small muted">${voicePhase==='recording'?'录音中 · 点击结束':voicePhase==='transcript'?'原话已准备好':'点击话筒开始'}</p><button class="mic ${voicePhase==='recording'?'recording':''}" data-action="${voicePhase==='recording'?'end-voice':'start-voice'}" aria-label="${voicePhase==='recording'?'结束录音':'开始录音'}">${icon('mic')}</button>${voicePhase==='recording'?`<div class="wave">${'<i></i>'.repeat(17)}</div><button class="linkbtn" style="margin:auto" data-action="cancel-voice">取消录音</button>`:`<h3>${voicePhase==='transcript'?'核对一下你的原话':'一次说出多个生活片段'}</h3><p class="small muted"></p>`}</section>${voiceError?`<div class="err show" role="alert">${E(voiceError)}</div><button class="secondary" data-action="voice-reset">${icon('retry')}重新尝试</button>`:''}${voicePhase==='transcript'?`<section class="card"><label for="transcript"><strong>识别原话</strong></label><textarea id="transcript" style="margin-top:12px">${E(voiceText)}</textarea><p class="notice"></p><button class="primary" data-action="process-voice" style="margin-top:15px">${icon('ai')}整理并保存记录</button></section>`:''}<p class="notice"></p></main>`}
let voiceScenario='success';
async function startVoice(){return FAWNSEE_MOBILE.recordVoiceStart();}
async function endVoice(){return FAWNSEE_MOBILE.recordVoiceStop();}
async function processVoice(){return FAWNSEE_MOBILE.recordVoiceSave();}
function voiceResult(id){let b=state.voiceBatches[id];if(!b)return notFound();let records=b.ids.map(id=>state.records.find(r=>r.id===id)).filter(Boolean);return `${header()}<main class="page">${back('整理结果')}<div class="checkmark">${icon('check')}</div><h1 style="text-align:center">已添加 ${records.length} 条记录</h1><p class="muted small" style="text-align:center">每个生活片段，都有了自己的位置。</p>${hero('voice','THREE SMALL MOMENTS','说过的日常<br>看得见的记录','可逐条检查、修改或删除。',true)}<section class="card"><h3>你的原话</h3><p class="small muted" style="margin-top:8px">“${E(b.text)}”</p></section><div class="timeline">${sorted(records).map(recordItem).join('')}</div><p class="form-note">${icon('info')}</p><div class="actions"><button class="primary" data-action="result-records" data-date="${b.date}">查看当日记录 ${icon('arrow')}</button><button class="secondary" data-action="voice-reset">${icon('mic')}继续说一段</button></div></main>`}
const TR={water:{label:'饮水量',unit:'毫升',cat:'water',key:'volume',aggregate:'sum'},calories:{label:'饮食热量',unit:'千卡',cat:'diet',key:'calories',aggregate:'sum'},activity:{label:'运动时长',unit:'分钟',cat:'activity',key:'duration',aggregate:'sum'},steps:{label:'步数',unit:'步',cat:'activity',key:'steps',aggregate:'sum'},sleep:{label:'睡眠时长',unit:'小时',cat:'sleep',key:'hours',aggregate:'sum'},environment:{label:'居住感受',unit:'分',cat:'environment',key:'quality',aggregate:'avg'},medical:{label:'医疗事项',unit:'次',cat:'medical',aggregate:'count'},weight:{label:'体重',unit:'kg',cat:'metric',key:'value',metric:'weight',aggregate:'avg'},glucose:{label:'血糖',unit:'mmol/L',cat:'metric',key:'value',metric:'glucose',aggregate:'avg'},bp_systolic:{label:'收缩压',unit:'mmHg',cat:'metric',key:'value',metric:'blood_pressure',aggregate:'avg'},bp_diastolic:{label:'舒张压',unit:'mmHg',cat:'metric',key:'diastolic',metric:'blood_pressure',aggregate:'avg'},lipids:{label:'血脂',unit:'mmol/L',cat:'metric',key:'value',metric:'lipids',aggregate:'avg'},height:{label:'身高',unit:'cm',cat:'metric',key:'value',metric:'height',aggregate:'avg'},custom:{label:'自定义指标',unit:'',cat:'metric',key:'value',metric:'custom',aggregate:'avg'}};
function dateShift(date,days){const d=new Date(date+'T12:00:00+08:00');d.setUTCDate(d.getUTCDate()+days);return d.toISOString().slice(0,10)}
function customTrendNames(){return [...new Set(state.records.filter(r=>r.cat==='metric'&&r.metric==='custom'&&r.metric_name).map(r=>r.metric_name))]}
function getTrend(){const c=TR[trendMetric];const names=trendMetric==='custom'?customTrendNames():[],pick=names.includes(trendName)?trendName:(names[0]||'');const end=trendRange==='custom'?(trendEnd||today()):today();const start=trendRange==='custom'?(trendStart||dateShift(end,-6)):dateShift(end,trendRange==='30'?-29:-6);const list=state.records.filter(r=>r.cat===c.cat&&r.date>=start&&r.date<=end&&(!c.metric||r.metric===c.metric)&&(trendMetric!=='glucose'||(r.unit===trendUnit&&(trendContext==='全部'||r.context===trendContext)))&&(trendMetric!=='custom'||!pick||r.metric_name===pick)&&(c.aggregate==='count'||(r[c.key]!==''&&r[c.key]!=null&&Number.isFinite(Number(r[c.key])))));const by={};for(let r of list)(by[r.date]??=[]).push(r);const points=Object.entries(by).sort(([a],[b])=>a.localeCompare(b)).map(([date,rs])=>({date,records:rs,value:c.aggregate==='count'?rs.length:c.aggregate==='sum'?rs.reduce((s,r)=>s+Number(r[c.key]),0):rs.reduce((s,r)=>s+Number(r[c.key]),0)/rs.length}));return{c,start,end,list,points,unit:trendMetric==='glucose'?trendUnit:(c.unit||list[0]?.unit||'')}}
function chart(data){const{points,start,end,unit}=data;if(!points.length)return`<section class="empty"><img src="${ASSETS.journal}" alt="安静的健康手账插画"><h3>这段时间还没有相关记录</h3><p class="small muted">切换指标或日期，或先留下一条记录。</p><button class="primary" data-go="#records">返回生活记录</button></section>`;const W=310,H=190,L=33,R=14,T=20,B=31,vals=points.map(x=>x.value),max=Math.max(...vals),min=Math.min(...vals);let span=Math.max(max-min,max*.12,.5),low=Math.max(0,min-span*.35),high=max+span*.35;let days=Math.max(1,(new Date(end)-new Date(start))/864e5);const x=d=>L+(new Date(d)-new Date(start))/864e5/days*(W-L-R);const y=v=>T+(high-v)/(high-low)*(H-T-B);let path='',prev=null;points.forEach(p=>{let consecutive=prev&&(new Date(p.date)-new Date(prev.date))/864e5===1;path+=`${consecutive?'L':'M'}${x(p.date)},${y(p.value)} `;prev=p});return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${data.c.label}趋势，单位${E(unit)}；点击数据点查看记录">${[0,1,2,3].map(i=>{let v=low+(high-low)*i/3,yy=y(v);return `<line class="grid" x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}"/><text x="${L-5}" y="${yy+4}" text-anchor="end">${Number(v.toFixed(1))}</text>`}).join('')}<path class="curve" d="${path}"/>${points.map((p,i)=>`<g><circle class="dot" cx="${x(p.date)}" cy="${y(p.value)}" r="6" tabindex="0" role="button" data-point="${p.date}" aria-label="${p.date} ${Number(p.value.toFixed(2))}${unit}，查看${p.records.length}条记录"/><text x="${x(p.date)}" y="${Math.max(12,y(p.value)-12)}" text-anchor="middle">${Number(p.value.toFixed(1))}</text></g>`).join('')}<text x="${L}" y="${H-5}">${start.slice(5)}</text><text x="${W-R}" y="${H-5}" text-anchor="end">${end.slice(5)}</text></svg>`}
function trendsPage(){const d=getTrend(),c=d.c,names=trendMetric==='custom'?customTrendNames():[],name=names.includes(trendName)?trendName:(names[0]||'');let values=d.list.map(r=>c.aggregate==='count'?1:Number(r[c.key])),total=values.reduce((s,n)=>s+n,0),avg=values.length?total/values.length:0;return `${header()}<main class="page f-trends-page">${back('趋势分析')}<section class="hero compact f-trends-hero"><img src="${ASSETS.journal}" alt="凡思原创健康手账插画"><div class="hero-content"><h2>看见生活的<br>细微轨迹</h2></div></section>${select('trend-metric','分析指标',Object.entries(TR).map(([k,c])=>[k,c.label]),trendMetric)}<div class="pillrow">${[['7','近 7 天'],['30','近 30 天'],['custom','自选日期']].map(([k,t])=>`<button class="chip ${trendRange===k?'active':''}" data-range="${k}">${t}</button>`).join('')}</div>${trendRange==='custom'?`<div class="grid2">${input('trend-start','开始日期','date',trendStart||dateShift(today(),-6))}${input('trend-end','结束日期','date',trendEnd||today())}</div>`:''}${trendMetric==='glucose'?`<div class="grid2">${select('trend-unit','血糖单位',['mmol/L','mg/dL'],trendUnit)}${select('trend-context','测量情境',['全部','未说明','空腹','餐前','餐后','随机'],trendContext)}</div>`:''}${trendMetric==='custom'?`<div class="grid2">${select('trend-name','指标名称',names.length?names:['暂无自定义指标'],name)}</div>`:''}<section class="chart-panel"><div class="row between"><h2>${c.label}</h2>${d.unit?`<span class="badge">${E(d.unit)}</span>`:''}</div><p class="chart-label">${d.start} — ${d.end}</p>${d.start>d.end?'<div class="err show">开始日期不能晚于结束日期。</div>':chart(d)}${d.points.length&&d.start<=d.end?`<div class="statgrid f-trends-statgrid"><div><span class="f-trends-stat-label" data-font-role="secondary">${c.aggregate==='avg'?'期间平均':'期间累计'}</span><b class="f-trends-stat-value" data-font-role="title">${c.aggregate==='avg'?Number(avg.toFixed(2)):Number(total.toFixed(2))}<small class="f-trends-stat-unit">${E(d.unit)}</small></b></div><div><span class="f-trends-stat-label" data-font-role="secondary">关联记录</span><b class="f-trends-stat-value" data-font-role="title">${d.list.length}<small class="f-trends-stat-unit">条</small></b></div></div>`:''}</section>${d.list.length?`<div class="section-head"><h2>关联记录</h2><span class="small muted">${d.list.length} 条</span></div><div class="timeline">${sorted(d.list).map(r=>`<p class="small muted" style="margin-top:10px">${r.date}</p>`+recordItem(r)).join('')}</div>`:''}</main>`}
function modal(title,body,buttons){const dlg=$('#dialog');dlg.innerHTML=`<section class="modal${String(body).includes('data-commerce-checkout')?' c11854-checkout-dialog':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">${title}</h2><p>${body}</p><div class="actions">${buttons.map((b,i)=>`<button type="button" class="${b.cls||'secondary'}"${String(body).includes('data-commerce-checkout')&&b.cls==='primary'?' data-font-role="body"':''} data-modal="${i}">${b.label}</button>`).join('')}</div></section>`;dlg.hidden=false;let previous=document.activeElement;dlg.querySelectorAll('[data-modal]').forEach(b=>b.onclick=()=>{dlg.hidden=true;dlg.innerHTML='';previous?.focus({preventScroll:true});buttons[Number(b.dataset.modal)].fn?.()});dlg.querySelector('button').focus({preventScroll:true})}
function isDirty(){if(globalThis.FAWNSEE_MEMBER_MODULES?.isDirty())return true;if(globalThis.FAWNSEE_TODAY_VIEWS?.dirty())return true;const f=$('#record-form');return !!f&&!!formBaseline&&new URLSearchParams(new FormData(f)).toString()!==formBaseline}
function go(to,force=false){to=globalThis.FAWNSEE_PHONE_AUTH?.guardRoute(to)||to;if(globalThis.FAWNSEE_MODULE_GATES?.blockRoute(to))return Promise.resolve(false);if(!FAWNSEE_MOBILE.user){const allowed=globalThis.FAWNSEE_GUEST_UI?.guardRoute(to);if(allowed===null){writeRouteHash(route,'replace');return Promise.resolve(false);}if(allowed)to=allowed;}if(saving||(todayPending&&!force))return;if(!force&&globalThis.FAWNSEE_MEMBER_MODULES?.isDirty()){modal('还没保存本次修改','继续填写，或放弃本次修改后离开。',[{label:'继续填写',cls:'primary'},{label:'放弃修改并离开',fn:()=>{globalThis.FAWNSEE_MEMBER_MODULES.clearDirty();go(to,true)}}]);return}if(!force&&globalThis.FAWNSEE_TODAY_VIEWS?.dirty()){modal('还没保存本次修改','继续填写，或放弃本次修改后离开。',[{label:'继续填写',cls:'primary'},{label:'放弃修改并离开',fn:()=>{globalThis.FAWNSEE_TODAY_VIEWS.clearDirty();globalThis.FAWNSEE_TODAY_AUX?.clearDirty();go(to,true)}}]);return}if(!force&&isDirty()){const f=$('#record-form'),cat=f.dataset.cat,vals=currentFormData();const choices=[{label:'继续填写',cls:'primary'}];if(!f.dataset.id)choices.push({label:'暂存草稿并离开',fn:async()=>{try{await FAWNSEE_RECORD_DRAFTS.save(cat,vals);go(to,true)}catch(error){toast(error.message||'草稿暂未保存，请继续填写')}}});choices.push({label:'放弃修改并离开',fn:()=>go(to,true)});modal('还没保存这份记录',f.dataset.id?'放弃本次修改后，原记录保持不变。':'你可以继续填写，或暂存草稿后离开。',choices);return}if(to===route)return Promise.resolve(false);return FAWNSEE_EXPERIENCE.navigate(to,hash=>FAWNSEE_MOBILE.prepareRoute(hash),commitRoute,e=>{toast(e.message);writeRouteHash(route,'replace')})}
function render(){const result=FAWNSEE_EXPERIENCE.render(renderApproved);globalThis.FAWNSEE_RECORD_PHOTOS?.afterRender();return result}
function renderApproved(){
 nav();if(globalThis.FAWNSEE_AUTH_ENTRIES?.render(route,()=>renderPrimary('login'),go))return;if(globalThis.FAWNSEE_GUEST_UI?.render(route))return;if(globalThis.FAWNSEE_PHONE_AUTH?.render(route))return;const [part,id]=route.slice(1).split('/');let html;
 if(part==='auth'&&['password','register'].includes(id)){$('#bottom').style.display='none';const authPage=id==='password'?'login':id;FAWNSEE_EXPERIENCE.primary(authPage,renderPrimary(authPage));return}
 const library=globalThis.FAWNSEE_TRY_LIBRARY?.render(route);if(library!==false&&library!==null&&library!==undefined){FAWNSEE_EXPERIENCE.setView(library);return}
 const member=globalThis.FAWNSEE_MEMBER_MODULES?.render(route);
 if(member!==null&&member!==undefined){FAWNSEE_EXPERIENCE.setView(member);globalThis.FAWNSEE_MEMBER_MODULES.afterRender();void 0;return}
 if(['today','ai','community','mine'].includes(part)&&route==='#'+part){FAWNSEE_EXPERIENCE.primary(part,renderPrimary(part));return}
 const tm=globalThis.FAWNSEE_TODAY?.matchRoute(route);
 if(tm&&globalThis.FAWNSEE_TODAY_VIEWS){const y=todayRestore?(state.today.ui.returnScroll[route]||0):window.scrollY;FAWNSEE_EXPERIENCE.setView(globalThis.FAWNSEE_TODAY_VIEWS.render(tm));globalThis.FAWNSEE_TODAY_VIEWS.afterRender();todayRestore=false;window.scrollTo(0,y);return}
 if(['ai','community','mine'].includes(part)){ FAWNSEE_EXPERIENCE.setView(header()+'<main class="page">'+back('页面暂未载入','#'+part)+'<section class="card"><p>请返回主页面继续。</p></section></main>');return}
 if(part==='form')html=CATS[id]?formPage(id):notFound();else if(part==='edit'){const r=state.records.find(x=>x.id===id);html=r?formPage(r.cat,id):notFound()}else if(part==='detail')html=detailPage(id);else if(part==='voice')html=voicePage();else if(part==='voice-result')html=voiceResult(id);else if(part==='trends')html=trendsPage();else html=recordsPage();FAWNSEE_EXPERIENCE.setView(html);const f=$('#record-form');if(f){formBaseline=new URLSearchParams(new FormData(f)).toString();f.addEventListener('submit',saveForm)}void 0}
document.addEventListener('click',e=>{const b=e.target.closest('[data-go],[data-filter],[data-volume],[data-metric],[data-delete],[data-range],[data-action],[data-point],[data-save-mode]');if(!b)return;if(b.dataset.saveMode){e.preventDefault();requestSave(b.dataset.saveMode);return}if(b.dataset.go){go(b.dataset.go);return}if(b.dataset.filter){filter=b.dataset.filter;render();return}if(b.dataset.volume){$('#f-volume').value=b.dataset.volume;return}if(b.dataset.metric){const f=$('#record-form'),m=b.dataset.metric;if(m===f.elements.metric.value)return;let date=f.elements.date.value,time=f.elements.time.value;lastMetric=m;const section=$('#record-form');let v=currentFormData();const old=Object.keys(v).some(k=>!['metric','date','time','unit','context','meal'].includes(k)&&v[k]!=='');const swap=()=>{if(!f.dataset.id)delete state.drafts.metric;let record= f.dataset.id?state.records.find(r=>r.id===f.dataset.id):null;if(record){toast('编辑时请保持原指标类型；新增另一类请返回记录入口。');return}render();$('#f-date').value=date;$('#f-time').value=time;formBaseline=new URLSearchParams(new FormData($('#record-form'))).toString()};if(old)modal('切换身体指标','切换后将清空尚未保存的本次数值。',[{label:'继续填写',cls:'primary'},{label:'切换并清空',fn:swap}]);else swap();return}if(b.dataset.delete){FAWNSEE_MOBILE.deleteRecord(b.dataset.delete);return;}if(false){let id=b.dataset.delete;modal('删除这条记录？','确认后，这条记录会从本会话的列表与趋势中移除。',[{label:'保留记录',cls:'primary'},{label:'确认删除',cls:'secondary danger',fn:()=>{const old=state.records;try{state.records=state.records.filter(r=>r.id!==id);persist();go('#records',true);toast('记录已删除')}catch{state.records=old;toast('删除失败，请重试')}}}]);return}if(b.dataset.range){trendRange=b.dataset.range;render();return}if(b.dataset.point){const d=getTrend(),rs=d.list.filter(r=>r.date===b.dataset.point);if(rs.length===1)go('#detail/'+rs[0].id);else modal(b.dataset.point+' · '+rs.length+' 条记录','请选择一条记录查看详情。',[...rs.map(r=>({label:sum(r),fn:()=>go('#detail/'+r.id)})),{label:'返回趋势',cls:'primary'}]);return}const a=b.dataset.action;if(a==='prev-date'||a==='next-date'){selectedDate=dateShift(selectedDate,a==='prev-date'?-1:1);render()}if(a==='start-voice')startVoice();if(a==='end-voice')endVoice();if(a==='process-voice')processVoice();if(a==='cancel-voice'){FAWNSEE_MOBILE.native('native.cancelVoice',{}).catch(()=>{});clearTimeout(voiceTimer);voicePhase='idle';voiceError='';render();toast('已取消，未添加记录')}if(a==='voice-reset'){clearTimeout(voiceTimer);voicePhase='idle';voiceError='';voiceScenario='success';go('#voice',true)}if(a==='result-records'){selectedDate=b.dataset.date;filter='all';go('#records',true)}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='voice-scenario')voiceScenario=t.value;if(t.id==='list-date'){selectedDate=t.value||today();render()}if(t.id==='f-unit'&&$('#f-metric')===null&&$('#record-form')?.elements.metric?.value==='glucose'&&$('#f-value')?.value){$('#f-value').value='';toast('单位已切换，请重新填写测量值')}if(t.id==='f-trend-metric'){trendMetric=t.value;render()}if(t.id==='f-trend-unit'){trendUnit=t.value;render()}if(t.id==='f-trend-context'){trendContext=t.value;render()}if(t.id==='f-trend-name'){trendName=t.value;render()}if(t.id==='f-trend-start'){trendStart=t.value;render()}if(t.id==='f-trend-end'){trendEnd=t.value;render()}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.isComposing&&e.target.matches('#record-form input:not([type=checkbox]):not([type=hidden])')){e.preventDefault();requestSave('done');return}if(e.key==='Escape'&&!$('#dialog').hidden){const first=$('#dialog button');first?.click()}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-point]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}if(!$('#dialog').hidden&&e.key==='Tab'){const buttons=[...$('#dialog').querySelectorAll('button')],a=buttons[0],b=buttons.at(-1);if(e.shiftKey&&document.activeElement===a){e.preventDefault();b.focus()}else if(!e.shiftKey&&document.activeElement===b){e.preventDefault();a.focus()}}});
window.addEventListener('message',handlePrimaryMessage);
// Opaque about:srcdoc previews cannot use URL History or Web Storage. Route state
// therefore lives in this document; ordinary http/file previews also mirror it to a hash.
function readRouteHash(){try{return window.location.hash||''}catch{return''}}
function writeRouteHash(to,mode='push'){try{if(!/^(https?:|file:)/i.test(window.location.href))return false;if(window.location.hash===to)return true;window.history[mode==='replace'?'replaceState':'pushState'](null,'',to);return true}catch{return false}}
function commitRoute(to){FAWNSEE_EXPERIENCE.remember();if(state.today&&to!==route){state.today.ui.returnScroll[route]=window.scrollY;todayRestore=true}if(to!==route&&voicePhase==='processing'){clearTimeout(voiceTimer);voicePhase='idle'}route=to;writeRouteHash(to);globalThis.FAWNSEE_MEMBER_MEMORY_EVENTS?.routeChanged(to);globalThis.FAWNSEE_FEEDBACK_TEST1?.routeChanged();render()}
window.addEventListener('hashchange',()=>{const next=readRouteHash()||'#today';if(next===route)return;if(saving){writeRouteHash(route,'replace');return}if(isDirty()){writeRouteHash(route,'replace');go(next);return}go(next)});
