  let c,h,match,formBaseline='';
  const field=(name,label,control,hint='')=>`<div class="t-field"><label for="t-${name}">${label}</label>${control}${hint?`<small>${hint}</small>`:''}</div>`;
  function input(name,label,value='',type='text',attrs='',hint=''){return field(name,label,`<input id="t-${name}" name="${name}" type="${type}" value="${h.esc(value??'')}" ${attrs}>`,hint);}
