    const total=summary.recentRecords.reduce((sum,x)=>sum+x.count,0),days=summary.recentRecords.filter(x=>x.count>0).length,max=Math.max(1,...summary.recentRecords.map(x=>x.count));
    const records=`<div class="bg-surface-container-lowest rounded-2xl p-4 border border-[#D9E2DE] shadow-[0_4px_16px_rgba(28,69,59,0.03)]"><div class="t-home-module-header"><h2>${h.ico('trend')}近七天记录</h2><span class="t-meta num">${summary.recentRecords[0].day.slice(5)} — ${M.day().slice(5)}</span></div><div class="t-home-bars">${summary.recentRecords.map(x=>`<button type="button" data-today-action="home-record-day" data-day="${x.day}" aria-label="${x.day}，${x.count}条生活记录"><b class="num">${x.count}<small>条</small></b><i style="height:${Math.max(4,x.count/max*68)}px;background:${x.day===M.day()?'#1C453B':'#20A9A5'}"></i><small class="num">${Number(x.day.slice(8))}日</small></button>`).join('')}</div><div class="t-home-module-header"><span class="t-meta">${days} 天留下记录<br><strong>共 ${total} 条生活片刻</strong></span>${h.routeButton('#records','去记录生活','t-small-primary')}</div></div>`;
