    return h.frame('goal-detail',{'goal-title':h.esc(g.title),'goal-status':g.status==='active'?'进行中':'已归档','goal-summary':cell('目标类型',M.GOAL_KINDS[g.kind])+cell('执行频率',M.GOAL_FREQUENCIES[g.frequency])+cell('提醒',h.esc(h.goalReminder(g))),'goal-today':`<div class="t-home-module-header"><h2>今日状态</h2><span class="t-meta num">${M.day()}</span></div><p class="t-helper">${checked?'今天已完成打卡':'今天还没有打卡'}${g.target!==null&&g.target!==''?` · 目标值 ${FAWNSEE_DOCUMENT_TODAY.formatTarget(g) ? h.esc(FAWNSEE_DOCUMENT_TODAY.formatTarget(g)) : ''}`:''}</p>${todayAction}`,'goal-calendar-card':`<div class="t-home-module-header"><h2>近 28 天</h2><span class="t-meta">累计 ${count}/28 天</span></div><p class="t-meta num">${M.addDays(M.day(),-27)} — ${M.day()}</p>${h.heatGrid(g,true)}<p class="t-meta">${g.status==='archived'?'已归档；可查看及撤销已有打卡。':'选择日期补记或撤销，不生成生活记录。'}</p>`,'goal-history':`<div class="t-home-module-header"><h2>打卡记录</h2><span class="t-meta">${g.entries.length} 条</span></div>${g.entries.length?g.entries.slice().sort((a,b)=>b.day.localeCompare(a.day)).map(e=>`<div class="t-home-arrangement"><strong class="num">${e.day}</strong><small>本人确认完成</small></div>`).join(''):'<p class="t-helper">暂无打卡记录。</p>'}`,'goal-actions':actions});
