  function cart(){const summary=c.store.cartSummary();return h.frame('cart',{'cart-header-count':`共 ${summary.quantity} 件`,'cart-items':summary.items.length?summary.items.map(line=>`<article class="t-cart-item"><img src="${h.art(line.product?.image_key||'goods')}" alt="原创商品示意"><div><button class="t-text-title" type="button" data-go="#today/goods/${line.product_id}">${h.esc(line.product?.name||'商品已不可用')}</button><p class="t-meta">${line.available?'价格':'已下架'} · ${h.money(line.product?.price_cents)}</p><div class="t-quantity-row"><div>${h.action('cart-minus',h.ico('back'),`data-id="${line.product_id}" data-quantity="${line.quantity}" aria-label="减少数量"`,'t-icon-button')}<input type="number" data-cart-quantity="${line.product_id}" min="0" max="999" step="1" value="${line.quantity}" aria-label="${h.esc(line.product?.name||'商品')}数量">${h.action('cart-plus',h.ico('plus'),`data-id="${line.product_id}" data-quantity="${line.quantity}" aria-label="增加数量"`,'t-icon-button')}</div>${h.action('cart-remove','移除',`data-id="${line.product_id}"`,'t-row-link')}</div></div></article>`).join(''):h.empty('购物车还是空的','去看看适合日常使用的小物。','#today/goods','探索好物','goods'),'cart-summary':`<div class="t-home-module-header"><span>合计 ${summary.quantity} 件</span><strong class="num t-product-price">${h.money(summary.total_cents)}</strong></div><p class="t-helper">虚拟订单，不会扣款。</p>${summary.items.length?h.action('cart-checkout','提交虚拟订单','','primary'):''}${h.routeButton('#today/goods','继续挑选好物','secondary')}`,'cart-notice':'当前不支持在线付款。'});}
