  model['record-summary']=`近七天 ${total} 条记录 · ${days} 天留下生活片刻`;
  summary.recentRecords.forEach((x,i)=>{model[`day${i}-label`]=i===6?'今日':'周'+['日','一','二','三','四','五','六'][new Date(x.day+'T12:00:00+08:00').getUTCDay()];model[`day${i}-date`]=Number(x.day.slice(8));model[`day${i}-title`]=`${x.day} · ${x.count}条生活记录`;model[`day${i}-value`]=x.day;model[`day${i}-opacity`]=x.count?1:.25;model[`day${i}-count`]=x.count;model[`day${i}-kinds`]=[...new Set(state.records.filter(r=>r.date===x.day).map(r=>r.cat).filter(k=>Object.prototype.hasOwnProperty.call(CATS,k)))].join(',');});
  const ordered=[...summary.activeGoals.filter(g=>g.kind==='water'),...summary.activeGoals.filter(g=>g.kind==='custom'),...summary.activeGoals.filter(g=>!['water','custom'].includes(g.kind))];
  for(let i=0;i<3;i++){const goal=ordered[i],checked=!!goal?.entries.some(e=>e.day===day);model[`goal${i}-kind`]=goal?.kind||'custom';model[`goal${i}-checked`]=String(checked);model[`goal${i}-style`]=goal?'':'display:none';model[`goal${i}-id`]=goal?.id||'';model[`goal${i}-route`]=goal?'#today/goals/'+goal.id:'#today/goals';model[`goal${i}-title`]=goal?.title||'';model[`goal${i}-description`]=goal?`${M.GOAL_FREQUENCIES[goal.frequency]}${goal.target?` · 目标值 ${FAWNSEE_DOCUMENT_TODAY.formatTarget(goal)}`:''}`:'';model[`goal${i}-status`]=checked?'已打卡':'未打卡';model[`goal${i}-action`]=checked?'goal-undo':'goal-checkin';model[`goal${i}-action-label`]=(checked?'撤销':'完成')+(goal?.title||'目标');model[`goal${i}-action-short`]=checked?'撤销':'打卡';model[`goal${i}-progress`]=checked?100:0;}
