 function init(context){ctx=context;model.init(ctx);return api;}
 function match(hash){const m=hash.match(/^#mine\/(profile|manage|password|membership|growth|invites|backup|privacy|display|help)(?:\/(restore|policy|terms))?$/);return m?{view:m[1],sub:m[2]||''}:null;}
 function button(action,label,cls='',extra=''){return `<button type="button" data-m-action="${action}" class="m-button ${cls}" ${extra}>${label}</button>`;}
 function go(route,label,cls=''){return `<button type="button" data-m-go="${E(route)}" class="m-button ${cls}">${label}</button>`;}
 function field(name,label,value='',attrs='',tag='input'){return `<label class="m-field"><span>${label}</span>${tag==='textarea'?`<textarea name="${name}" ${attrs}>${E(value)}</textarea>`:`<input name="${name}" id="m-${name}" value="${E(value??'')}" ${attrs}>`}</label>`;}
 function select(name,label,value,options){return `<label class="m-field"><span>${label}</span><select name="${name}">${Object.entries(options).map(([k,v])=>`<option value="${E(k)}" ${String(value)===k?'selected':''}>${E(v)}</option>`).join('')}</select></label>`;}
 const formError=()=>`<p id="mine-error" class="m-error" role="alert" ${error?'':'hidden'}>${E(error)}</p>`;
